import React from 'react';
import { render, screen, cleanup, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { ProfileInfoForm } from '@/components/account/ProfileInfoForm';
import { ChangePasswordForm } from '@/components/account/ChangePasswordForm';
import { useAuth } from '@/context/AuthContext';

jest.mock('@/context/AuthContext');
jest.mock('@/lib/client-api');

const mockUseAuth = useAuth as jest.MockedFunction<typeof useAuth>;

describe('ProfileInfoForm', () => {
  const mockUser = {
    _id: '123',
    fullName: 'Nguyß╗àn V─ân A',
    email: 'nguyen@example.com',
    phone: '0901234567',
    role: 'PARTICIPANT' as const,
    accountStatus: 'ACTIVE' as const,
    createdAt: '2026-01-01',
    updatedAt: '2026-01-01',
  };

  let mockRefreshUser: jest.Mock;

  beforeEach(() => {
    jest.clearAllMocks();
    mockRefreshUser = jest.fn();
    mockUseAuth.mockReturnValue({
      user: mockUser,
      loading: false,
      refreshUser: mockRefreshUser,
      login: jest.fn(),
      register: jest.fn(),
      loginWithGoogle: jest.fn(),
      logout: jest.fn(),
    } as any);
  });

  afterEach(() => {
    cleanup();
  });

  describe('rendering', () => {
    it('should render form title', () => {
      render(<ProfileInfoForm />);
      expect(screen.getByText('Th├┤ng tin c├í nh├ón')).toBeInTheDocument();
    });

    it('should render full name field', () => {
      render(<ProfileInfoForm />);
      expect(screen.getByLabelText(/hß╗ì v├á t├¬n/i)).toBeInTheDocument();
    });

    it('should render email field as read-only', () => {
      render(<ProfileInfoForm />);
      const emailInput = screen.getByLabelText(/email/i);
      expect(emailInput).toHaveAttribute('readOnly');
      expect(emailInput).toHaveValue(mockUser.email);
    });

    it('should show helper text for email field', () => {
      render(<ProfileInfoForm />);
      expect(screen.getByText(/email ─æ─âng nhß║¡p kh├┤ng thß╗â thay ─æß╗òi/i)).toBeInTheDocument();
    });

    it('should render phone field as read-only', () => {
      render(<ProfileInfoForm />);
      const phoneInput = screen.getByLabelText(/sß╗æ ─æiß╗çn thoß║íi/i);
      expect(phoneInput).toHaveAttribute('readOnly');
      expect(phoneInput).toHaveValue(mockUser.phone);
    });

    it('should pre-fill full name from user context', () => {
      render(<ProfileInfoForm />);
      const nameInput = screen.getByLabelText(/hß╗ì v├á t├¬n/i) as HTMLInputElement;
      expect(nameInput.value).toBe(mockUser.fullName);
    });

    it('should render save button', () => {
      render(<ProfileInfoForm />);
      expect(screen.getByRole('button', { name: /l╞░u thay ─æß╗òi/i })).toBeInTheDocument();
    });

    it('should render section with correct semantic HTML', () => {
      const { container } = render(<ProfileInfoForm />);
      const section = container.querySelector('section');
      expect(section).toBeInTheDocument();
      expect(section?.tagName).toBe('SECTION');
    });
  });

  describe('form behavior', () => {
    it('should disable save button when no changes made', () => {
      render(<ProfileInfoForm />);
      const saveBtn = screen.getByRole('button', { name: /l╞░u thay ─æß╗òi/i });
      expect(saveBtn).toBeDisabled();
    });

    it('should enable save button when name changes', async () => {
      const user = userEvent.setup();
      render(<ProfileInfoForm />);
      const nameInput = screen.getByLabelText(/hß╗ì v├á t├¬n/i);
      await user.clear(nameInput);
      await user.type(nameInput, 'Nguyß╗àn V─ân B');
      const saveBtn = screen.getByRole('button', { name: /l╞░u thay ─æß╗òi/i });
      expect(saveBtn).not.toBeDisabled();
    });

    it('should disable save button when reverting to original name', async () => {
      const user = userEvent.setup();
      render(<ProfileInfoForm />);
      const nameInput = screen.getByLabelText(/hß╗ì v├á t├¬n/i);
      await user.clear(nameInput);
      await user.type(nameInput, 'Different Name');
      await user.clear(nameInput);
      await user.type(nameInput, mockUser.fullName);
      const saveBtn = screen.getByRole('button', { name: /l╞░u thay ─æß╗òi/i });
      expect(saveBtn).toBeDisabled();
    });

    it('should show validation error when submitting empty name', async () => {
      const user = userEvent.setup();
      render(<ProfileInfoForm />);
      const nameInput = screen.getByLabelText(/hß╗ì v├á t├¬n/i);
      await user.clear(nameInput);
      const saveBtn = screen.getByRole('button', { name: /l╞░u thay ─æß╗òi/i });
      await user.type(nameInput, ' ');
      await user.clear(nameInput);
      expect(saveBtn).not.toBeDisabled();
      await user.click(saveBtn);
      expect(screen.getByText(/hß╗ì v├á t├¬n kh├┤ng ─æ╞░ß╗úc ─æß╗â trß╗æng/i)).toBeInTheDocument();
    });

    it('should have error alert with proper aria-live', async () => {
      const user = userEvent.setup();
      render(<ProfileInfoForm />);
      const nameInput = screen.getByLabelText(/hß╗ì v├á t├¬n/i);
      await user.clear(nameInput);
      await user.type(nameInput, ' ');
      await user.clear(nameInput);
      const saveBtn = screen.getByRole('button', { name: /l╞░u thay ─æß╗òi/i });
      await user.click(saveBtn);
      const alert = screen.getByRole('alert');
      expect(alert).toHaveAttribute('aria-live', 'assertive');
    });

    it('should handle missing fullName gracefully', () => {
      mockUseAuth.mockReturnValue({
        user: { ...mockUser, fullName: '' },
        loading: false,
        refreshUser: mockRefreshUser,
        login: jest.fn(),
        register: jest.fn(),
        loginWithGoogle: jest.fn(),
        logout: jest.fn(),
      } as any);

      render(<ProfileInfoForm />);
      const nameInput = screen.getByLabelText(/hß╗ì v├á t├¬n/i) as HTMLInputElement;
      expect(nameInput.value).toBe('');
    });

    it('should display fallback text for missing phone', () => {
      mockUseAuth.mockReturnValue({
        user: { ...mockUser, phone: undefined },
        loading: false,
        refreshUser: mockRefreshUser,
        login: jest.fn(),
        register: jest.fn(),
        loginWithGoogle: jest.fn(),
        logout: jest.fn(),
      } as any);

      render(<ProfileInfoForm />);
      const phoneInput = screen.getByLabelText(/sß╗æ ─æiß╗çn thoß║íi/i) as HTMLInputElement;
      expect(phoneInput.value).toBe('Ch╞░a cß║¡p nhß║¡t');
    });
  });
});

describe('ChangePasswordForm', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  afterEach(() => {
    cleanup();
  });

  describe('rendering', () => {
    it('should render form title', () => {
      render(<ChangePasswordForm />);
      expect(screen.getByText('─Éß╗òi mß║¡t khß║⌐u')).toBeInTheDocument();
    });

    it('should render current password field', () => {
      render(<ChangePasswordForm />);
      expect(screen.getByLabelText(/mß║¡t khß║⌐u hiß╗çn tß║íi/i)).toBeInTheDocument();
    });

    it('should render new password field', () => {
      const { container } = render(<ChangePasswordForm />);
      // Get by ID to avoid label text conflicts
      const newPwdField = container.querySelector('#newPassword');
      expect(newPwdField).toBeInTheDocument();
    });

    it('should render confirm password field', () => {
      render(<ChangePasswordForm />);
      expect(screen.getByLabelText(/x├íc nhß║¡n mß║¡t khß║⌐u mß╗¢i/i)).toBeInTheDocument();
    });

    it('should show helper text for new password', () => {
      render(<ChangePasswordForm />);
      expect(screen.getByText(/├¡t nhß║Ñt 6 k├╜ tß╗▒/i)).toBeInTheDocument();
    });

    it('should render update button', () => {
      render(<ChangePasswordForm />);
      expect(screen.getByRole('button', { name: /cß║¡p nhß║¡t mß║¡t khß║⌐u/i })).toBeInTheDocument();
    });

    it('should start with empty password fields', () => {
      render(<ChangePasswordForm />);
      const inputs = screen.getAllByDisplayValue('');
      expect(inputs.length).toBeGreaterThan(0);
    });
  });

  describe('validation', () => {
    it('should reject new password shorter than 6 characters', async () => {
      const user = userEvent.setup();
      const { container } = render(<ChangePasswordForm />);
      const currentPwd = container.querySelector('#currentPassword') as HTMLInputElement;
      const newPwd = container.querySelector('#newPassword') as HTMLInputElement;
      const confirmPwd = container.querySelector('#confirmPassword') as HTMLInputElement;
      const submitBtn = screen.getByRole('button', { name: /cß║¡p nhß║¡t/i });

      await user.type(currentPwd, 'oldpass123');
      await user.type(newPwd, 'short');
      await user.type(confirmPwd, 'short');
      await user.click(submitBtn);

      expect(screen.getByText(/mß║¡t khß║⌐u mß╗¢i phß║úi c├│ ├¡t nhß║Ñt 6 k├╜ tß╗▒/i)).toBeInTheDocument();
    });

    it('should reject mismatched password confirmation', async () => {
      const user = userEvent.setup();
      const { container } = render(<ChangePasswordForm />);
      const newPwd = container.querySelector('#newPassword') as HTMLInputElement;
      const confirmPwd = container.querySelector('#confirmPassword') as HTMLInputElement;

      await user.type(newPwd, 'newpass123');
      await user.type(confirmPwd, 'different123');

      expect(screen.getByText(/mß║¡t khß║⌐u x├íc nhß║¡n kh├┤ng khß╗¢p/i)).toBeInTheDocument();
    });

    it('should clear error when user corrects mismatched confirmation', async () => {
      const user = userEvent.setup();
      const { container } = render(<ChangePasswordForm />);
      const newPwd = container.querySelector('#newPassword') as HTMLInputElement;
      const confirmPwd = container.querySelector('#confirmPassword') as HTMLInputElement;

      await user.type(newPwd, 'newpass123');
      await user.type(confirmPwd, 'different');

      expect(screen.getByText(/mß║¡t khß║⌐u x├íc nhß║¡n kh├┤ng khß╗¢p/i)).toBeInTheDocument();

      await user.clear(confirmPwd);
      await user.type(confirmPwd, 'newpass123');

      expect(screen.queryByText(/mß║¡t khß║⌐u x├íc nhß║¡n kh├┤ng khß╗¢p/i)).not.toBeInTheDocument();
    });

    it('should have error alert with proper aria-live when validation fails', async () => {
      const user = userEvent.setup();
      render(<ChangePasswordForm />);
      const submitBtn = screen.getByRole('button', { name: /cß║¡p nhß║¡t mß║¡t khß║⌐u/i });

      await user.click(submitBtn);

      const alert = screen.getByRole('alert');
      expect(alert).toHaveAttribute('aria-live', 'assertive');
    });
  });

  describe('accessibility', () => {
    it('should have proper label associations', () => {
      render(<ChangePasswordForm />);
      const currentPwd = screen.getByLabelText(/mß║¡t khß║⌐u hiß╗çn tß║íi/i);
      expect(currentPwd).toHaveAttribute('id', 'currentPassword');
    });

    it('should have password show/hide toggle on password fields', () => {
      const { container } = render(<ChangePasswordForm />);
      const form = container.querySelector('form')!;
      const eyeButtons = within(form).getAllByRole('button').filter((b) =>
        b.getAttribute('aria-label')?.match(/Hiß╗çn|ß║¿n/)
      );
      expect(eyeButtons.length).toBeGreaterThan(0);
    });
  });
});

import React from 'react';
import { render, screen, waitFor } from '@testing-library/react';
import { RoleGuard } from '@/components/auth/RoleGuard';
import { useAuth } from '@/context/AuthContext';
import type { User } from '@/context/AuthContext';

jest.mock('@/context/AuthContext');

const mockUseAuth = useAuth as jest.MockedFunction<typeof useAuth>;

const mockUser = (role: User['role']): User => ({
  _id: '123',
  fullName: 'Test User',
  email: 'test@example.com',
  phone: '0123456789',
  role,
  accountStatus: 'ACTIVE',
  createdAt: '2026-01-01',
  updatedAt: '2026-01-01',
});

describe('RoleGuard', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  describe('loading state', () => {
    it('should show spinner while loading', () => {
      mockUseAuth.mockReturnValue({
        user: null,
        loading: true,
        login: jest.fn(),
        register: jest.fn(),
        loginWithGoogle: jest.fn(),
        logout: jest.fn(),
        refreshUser: jest.fn(),
      } as any);

      render(
        <RoleGuard allow={['PARTICIPANT']}>
          <div>Protected Content</div>
        </RoleGuard>
      );

      const spinner = document.querySelector('.animate-spin');
      expect(spinner).toBeInTheDocument();
    });

    it('should not show protected content during loading', () => {
      mockUseAuth.mockReturnValue({
        user: null,
        loading: true,
        login: jest.fn(),
        register: jest.fn(),
        loginWithGoogle: jest.fn(),
        logout: jest.fn(),
        refreshUser: jest.fn(),
      } as any);

      render(
        <RoleGuard allow={['PARTICIPANT']}>
          <div>Protected Content</div>
        </RoleGuard>
      );

      expect(screen.queryByText('Protected Content')).not.toBeInTheDocument();
    });

    it('should display full-screen spinner', () => {
      mockUseAuth.mockReturnValue({
        user: null,
        loading: true,
        login: jest.fn(),
        register: jest.fn(),
        loginWithGoogle: jest.fn(),
        logout: jest.fn(),
        refreshUser: jest.fn(),
      } as any);

      const { container } = render(
        <RoleGuard allow={['PARTICIPANT']}>
          <div>Protected Content</div>
        </RoleGuard>
      );

      const loader = container.querySelector('div');
      expect(loader).toHaveStyle({ height: 'height: 100dvh' });
    });
  });

  describe('allowed roles', () => {
    it('should render children for allowed role', () => {
      mockUseAuth.mockReturnValue({
        user: mockUser('PARTICIPANT'),
        loading: false,
        login: jest.fn(),
        register: jest.fn(),
        loginWithGoogle: jest.fn(),
        logout: jest.fn(),
        refreshUser: jest.fn(),
      } as any);

      render(
        <RoleGuard allow={['PARTICIPANT']}>
          <div>Protected Content</div>
        </RoleGuard>
      );

      expect(screen.getByText('Protected Content')).toBeInTheDocument();
    });

    it('should render children for ADMIN role when allowed', () => {
      mockUseAuth.mockReturnValue({
        user: mockUser('ADMIN'),
        loading: false,
        login: jest.fn(),
        register: jest.fn(),
        loginWithGoogle: jest.fn(),
        logout: jest.fn(),
        refreshUser: jest.fn(),
      } as any);

      render(
        <RoleGuard allow={['ADMIN']}>
          <div>Admin Only</div>
        </RoleGuard>
      );

      expect(screen.getByText('Admin Only')).toBeInTheDocument();
    });

    it('should render children for ORGANIZER role when allowed', () => {
      mockUseAuth.mockReturnValue({
        user: mockUser('ORGANIZER'),
        loading: false,
        login: jest.fn(),
        register: jest.fn(),
        loginWithGoogle: jest.fn(),
        logout: jest.fn(),
        refreshUser: jest.fn(),
      } as any);

      render(
        <RoleGuard allow={['ORGANIZER']}>
          <div>Organizer Only</div>
        </RoleGuard>
      );

      expect(screen.getByText('Organizer Only')).toBeInTheDocument();
    });

    it('should render children for STAFF role when allowed', () => {
      mockUseAuth.mockReturnValue({
        user: mockUser('STAFF'),
        loading: false,
        login: jest.fn(),
        register: jest.fn(),
        loginWithGoogle: jest.fn(),
        logout: jest.fn(),
        refreshUser: jest.fn(),
      } as any);

      render(
        <RoleGuard allow={['STAFF']}>
          <div>Staff Only</div>
        </RoleGuard>
      );

      expect(screen.getByText('Staff Only')).toBeInTheDocument();
    });

    it('should render children when role is in allowed array', () => {
      mockUseAuth.mockReturnValue({
        user: mockUser('ORGANIZER'),
        loading: false,
        login: jest.fn(),
        register: jest.fn(),
        loginWithGoogle: jest.fn(),
        logout: jest.fn(),
        refreshUser: jest.fn(),
      } as any);

      render(
        <RoleGuard allow={['ADMIN', 'ORGANIZER', 'PARTICIPANT']}>
          <div>Multi-role Content</div>
        </RoleGuard>
      );

      expect(screen.getByText('Multi-role Content')).toBeInTheDocument();
    });
  });

  describe('denied roles', () => {
    it('should show access denied for disallowed role', () => {
      mockUseAuth.mockReturnValue({
        user: mockUser('PARTICIPANT'),
        loading: false,
        login: jest.fn(),
        register: jest.fn(),
        loginWithGoogle: jest.fn(),
        logout: jest.fn(),
        refreshUser: jest.fn(),
      } as any);

      render(
        <RoleGuard allow={['ADMIN']}>
          <div>Admin Only</div>
        </RoleGuard>
      );

      expect(screen.queryByText('Admin Only')).not.toBeInTheDocument();
      expect(screen.getByText(/quyß╗ün truy cß║¡p bß╗ï tß╗½ chß╗æi/i)).toBeInTheDocument();
    });

    it('should show default message for denied access', () => {
      mockUseAuth.mockReturnValue({
        user: mockUser('PARTICIPANT'),
        loading: false,
        login: jest.fn(),
        register: jest.fn(),
        loginWithGoogle: jest.fn(),
        logout: jest.fn(),
        refreshUser: jest.fn(),
      } as any);

      render(
        <RoleGuard allow={['ADMIN']}>
          <div>Admin Only</div>
        </RoleGuard>
      );

      expect(
        screen.getByText(/bß║ín kh├┤ng c├│ quyß╗ün truy cß║¡p khu vß╗▒c n├áy/i)
      ).toBeInTheDocument();
    });

    it('should show custom title when denied', () => {
      mockUseAuth.mockReturnValue({
        user: mockUser('STAFF'),
        loading: false,
        login: jest.fn(),
        register: jest.fn(),
        loginWithGoogle: jest.fn(),
        logout: jest.fn(),
        refreshUser: jest.fn(),
      } as any);

      render(
        <RoleGuard allow={['ADMIN']} title="Admin Access Required">
          <div>Admin Only</div>
        </RoleGuard>
      );

      expect(screen.getByText('Admin Access Required')).toBeInTheDocument();
    });

    it('should show custom message when denied', () => {
      mockUseAuth.mockReturnValue({
        user: mockUser('PARTICIPANT'),
        loading: false,
        login: jest.fn(),
        register: jest.fn(),
        loginWithGoogle: jest.fn(),
        logout: jest.fn(),
        refreshUser: jest.fn(),
      } as any);

      render(
        <RoleGuard
          allow={['ORGANIZER']}
          message="Only event organizers can access this page."
        >
          <div>Organizer Only</div>
        </RoleGuard>
      );

      expect(
        screen.getByText('Only event organizers can access this page.')
      ).toBeInTheDocument();
    });

    it('should show both custom title and message', () => {
      mockUseAuth.mockReturnValue({
        user: mockUser('PARTICIPANT'),
        loading: false,
        login: jest.fn(),
        register: jest.fn(),
        loginWithGoogle: jest.fn(),
        logout: jest.fn(),
        refreshUser: jest.fn(),
      } as any);

      render(
        <RoleGuard
          allow={['ADMIN']}
          title="Restricted Area"
          message="Contact support for access."
        >
          <div>Restricted</div>
        </RoleGuard>
      );

      expect(screen.getByText('Restricted Area')).toBeInTheDocument();
      expect(screen.getByText('Contact support for access.')).toBeInTheDocument();
    });
  });

  describe('unauthenticated access', () => {
    it('should show access denied for null user', () => {
      mockUseAuth.mockReturnValue({
        user: null,
        loading: false,
        login: jest.fn(),
        register: jest.fn(),
        loginWithGoogle: jest.fn(),
        logout: jest.fn(),
        refreshUser: jest.fn(),
      } as any);

      render(
        <RoleGuard allow={['PARTICIPANT']}>
          <div>Protected Content</div>
        </RoleGuard>
      );

      expect(screen.queryByText('Protected Content')).not.toBeInTheDocument();
      expect(
        screen.getByText(/quyß╗ün truy cß║¡p bß╗ï tß╗½ chß╗æi/i)
      ).toBeInTheDocument();
    });

    it('should show default message for unauthenticated user', () => {
      mockUseAuth.mockReturnValue({
        user: null,
        loading: false,
        login: jest.fn(),
        register: jest.fn(),
        loginWithGoogle: jest.fn(),
        logout: jest.fn(),
        refreshUser: jest.fn(),
      } as any);

      render(
        <RoleGuard allow={['ADMIN']}>
          <div>Admin Only</div>
        </RoleGuard>
      );

      expect(
        screen.getByText(/bß║ín kh├┤ng c├│ quyß╗ün truy cß║¡p khu vß╗▒c n├áy/i)
      ).toBeInTheDocument();
    });
  });

  describe('access denied screen', () => {
    it('should display shield icon on denied access', () => {
      mockUseAuth.mockReturnValue({
        user: mockUser('PARTICIPANT'),
        loading: false,
        login: jest.fn(),
        register: jest.fn(),
        loginWithGoogle: jest.fn(),
        logout: jest.fn(),
        refreshUser: jest.fn(),
      } as any);

      const { container } = render(
        <RoleGuard allow={['ADMIN']}>
          <div>Admin Only</div>
        </RoleGuard>
      );

      // Check for SVG element (lucide-react ShieldAlert)
      const svg = container.querySelector('svg');
      expect(svg).toBeInTheDocument();
    });

    it('should display back to home link', () => {
      mockUseAuth.mockReturnValue({
        user: mockUser('STAFF'),
        loading: false,
        login: jest.fn(),
        register: jest.fn(),
        loginWithGoogle: jest.fn(),
        logout: jest.fn(),
        refreshUser: jest.fn(),
      } as any);

      render(
        <RoleGuard allow={['ORGANIZER']}>
          <div>Organizer Only</div>
        </RoleGuard>
      );

      const homeLink = screen.getByRole('link', { name: /vß╗ü trang chß╗º/i });
      expect(homeLink).toHaveAttribute('href', '/');
    });

    it('should be full-screen on denied access', () => {
      mockUseAuth.mockReturnValue({
        user: mockUser('PARTICIPANT'),
        loading: false,
        login: jest.fn(),
        register: jest.fn(),
        loginWithGoogle: jest.fn(),
        logout: jest.fn(),
        refreshUser: jest.fn(),
      } as any);

      const { container } = render(
        <RoleGuard allow={['ADMIN']}>
          <div>Admin Only</div>
        </RoleGuard>
      );

      const wrapper = container.firstChild;
      expect(wrapper).toHaveStyle({ height: 'height: 100dvh' });
    });
  });

  describe('multiple roles', () => {
    it('should allow access if user has any of multiple allowed roles', () => {
      mockUseAuth.mockReturnValue({
        user: mockUser('ORGANIZER'),
        loading: false,
        login: jest.fn(),
        register: jest.fn(),
        loginWithGoogle: jest.fn(),
        logout: jest.fn(),
        refreshUser: jest.fn(),
      } as any);

      render(
        <RoleGuard allow={['ADMIN', 'ORGANIZER', 'PARTICIPANT']}>
          <div>Multi-role Protected</div>
        </RoleGuard>
      );

      expect(screen.getByText('Multi-role Protected')).toBeInTheDocument();
    });

    it('should deny access if user not in multiple allowed roles', () => {
      mockUseAuth.mockReturnValue({
        user: mockUser('PARTICIPANT'),
        loading: false,
        login: jest.fn(),
        register: jest.fn(),
        loginWithGoogle: jest.fn(),
        logout: jest.fn(),
        refreshUser: jest.fn(),
      } as any);

      render(
        <RoleGuard allow={['ADMIN', 'ORGANIZER']}>
          <div>Restricted to Admins and Organizers</div>
        </RoleGuard>
      );

      expect(
        screen.queryByText('Restricted to Admins and Organizers')
      ).not.toBeInTheDocument();
      expect(
        screen.getByText(/quyß╗ün truy cß║¡p bß╗ï tß╗½ chß╗æi/i)
      ).toBeInTheDocument();
    });
  });

