          type,
          href: expectedHref,
        });
        expect(notif!.title.trim().length).toBeGreaterThan(0);
        expect(notif!.message.trim().length).toBeGreaterThan(0);
        expect(Number.isNaN(Date.parse(notif!.createdAt))).toBe(false);
