interface EditForm {
  title: string
  organizer: string
  location: string
  categoryId: string
  capacity: string
  startDate: string
  endDate: string
  banner: string
  description: string
  privacy: "public" | "private"
  isFeatured: boolean
  isTrending: boolean
}

interface CategoryItem {
  _id: string
  name: string
}

/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ Helpers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */

function formatDate(value?: string) {
  if (!value) return "ΓÇö"
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return "ΓÇö"
  return date.toLocaleDateString("vi-VN", { day: "2-digit", month: "2-digit", year: "numeric" })
}

function toIso(value: string): string {
  if (!value) return ""
  return new Date(value).toISOString()
}

function toLocal(value?: string): string {
  if (!value) return ""
  const d = new Date(value)
  if (Number.isNaN(d.getTime())) return ""
  const pad = (n: number) => String(n).padStart(2, "0")
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`
}

function makeEditForm(event: AdminEvent): EditForm {
  const catId = typeof event.categoryId === "object" ? event.categoryId?._id ?? "" : event.categoryId ?? ""
  return {
    title: event.title,
    organizer: event.organizer ?? "",
    location: event.location ?? "",
    categoryId: catId,
    capacity: String(event.capacity ?? event.maxAttendees ?? ""),
    startDate: toLocal(event.startDate ?? event.date),
    endDate: toLocal(event.endDate),
    banner: event.banner ?? event.imageUrl ?? event.posterImage ?? "",
    description: event.description ?? "",
    privacy: event.privacy ?? "public",
    isFeatured: event.isFeatured ?? false,
    isTrending: event.isTrending ?? false,
  }
}

function reviewBadge(reviewStatus: ReviewStatus): "secondary" | "success" | "warning" | "destructive" {
  if (reviewStatus === "PUBLISHED") return "success"
  if (reviewStatus === "PENDING_REVIEW" || reviewStatus === "APPROVED_WAITING_DEPOSIT") return "warning"
  if (reviewStatus === "REJECTED") return "destructive"
  return "secondary"
}

function statusLabel(event: AdminEvent): string {
  if (event.privacy === "private") return "Ri├¬ng t╞░"
  if (event.status === "completed") return "─É├ú qua"
  if (event.status === "cancelled") return "─É├ú hß╗ºy"
  return "C├┤ng khai"
}

function statusClass(event: AdminEvent): string {
  if (event.privacy === "private") return "text-amber-600"
  if (event.status === "completed") return "text-cyan-600"
  if (event.status === "cancelled") return "text-rose-600"
  return "text-emerald-600"
}

