"use client"

import { useCallback, useEffect, useState } from "react"
import Link from "next/link"
import { Check, X, Building2, MapPin, Inbox, Eye, Loader2 } from "lucide-react"
import { cn } from "@/lib/utils"
import { Badge } from "@/components/ui/badge"
import { ModerationDecisionModal } from "@/components/moderation/ModerationDecisionModal"
import {
  approveEvent,
  fetchModerationQueue,
  rejectEvent,
} from "@/components/moderation/moderation-api"
import type { ModerationEvent, ModerationStatus } from "@/types"

type ReviewQueueTab = Extract<ModerationStatus, "pending" | "waiting_deposit">

const TABS: { id: ReviewQueueTab; label: string }[] = [
  { id: "pending", label: "Chß╗¥ duyß╗çt" },
  { id: "waiting_deposit", label: "Chß╗¥ cß╗ìc" },
]

type Buckets = Record<ReviewQueueTab, ModerationEvent[]>
const EMPTY: Buckets = { pending: [], waiting_deposit: [] }

/** Admin moderation queue ΓÇö wired to /api/admin/events. */
export default function ModerationPage() {
  const [data, setData] = useState<Buckets>(EMPTY)
  const [tab, setTab] = useState<ReviewQueueTab>("pending")
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [busyId, setBusyId] = useState<string | null>(null)
  const [rejectFor, setRejectFor] = useState<ModerationEvent | null>(null)

  const reload = useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      const [pending, waiting_deposit] = await Promise.all([
        fetchModerationQueue("pending"),
        fetchModerationQueue("waiting_deposit"),
      ])
      setData({ pending, waiting_deposit })
    } catch (err) {
      setError(err instanceof Error ? err.message : "Kh├┤ng tß║úi ─æ╞░ß╗úc danh s├ích kiß╗âm duyß╗çt")
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    void reload()
  }, [reload])

  const approve = async (id: string) => {
    setBusyId(id)
    try {
      await approveEvent(id)
      await reload()
    } catch (err) {
      setError(err instanceof Error ? err.message : "Duyß╗çt sß╗▒ kiß╗çn thß║Ñt bß║íi")
    } finally {
      setBusyId(null)
    }
  }

  const confirmReject = async (reason?: string) => {
    if (!rejectFor || !reason) return
    const id = rejectFor.id
    setRejectFor(null)
    setBusyId(id)
    try {
      await rejectEvent(id, reason)
      await reload()
    } catch (err) {
      setError(err instanceof Error ? err.message : "Tß╗½ chß╗æi sß╗▒ kiß╗çn thß║Ñt bß║íi")
    } finally {
      setBusyId(null)
    }
  }

  const count = (status: ReviewQueueTab) => data[status].length
  const rows = data[tab]

  return (
    <div className="space-y-6 animate-fade-up">
      <div>
        <h2 className="text-2xl font-bold text-foreground">Kiß╗âm duyß╗çt sß╗▒ kiß╗çn</h2>
        <p className="mt-1 text-sm text-muted-foreground">
          X├⌐t duyß╗çt c├íc sß╗▒ kiß╗çn do Ban tß╗ò chß╗⌐c gß╗¡i l├¬n tr╞░ß╗¢c khi c├┤ng bß╗æ.
        </p>
      </div>

      {error && (
        <div role="alert" className="rounded-xl border border-rose-300/60 bg-rose-500/10 px-4 py-3 text-sm text-rose-600 dark:text-rose-400">
          {error}
        </div>
      )}

      {/* Tabs */}
      <div className="flex flex-wrap gap-2">
        {TABS.map((t) => (
          <button
            key={t.id}
            type="button"
            onClick={() => setTab(t.id)}
            className={cn(
              "inline-flex items-center gap-2 rounded-xl px-4 py-2 text-sm font-semibold transition-colors",
              tab === t.id
                ? "bg-cyan-600 text-white shadow-sm"
                : "border border-border bg-card text-muted-foreground hover:bg-muted"
            )}
          >
            {t.label}
            <span
              className={cn(
                "rounded-full px-1.5 py-0.5 text-xs font-bold",
                tab === t.id ? "bg-white/20" : "bg-muted"
              )}
            >
              {count(t.id)}
            </span>
          </button>
        ))}
      </div>

      {/* List */}
      <div className="overflow-hidden rounded-2xl border border-border bg-card shadow-sm">
        {loading ? (
          <div className="flex h-64 flex-col items-center justify-center gap-2 text-muted-foreground">
            <Loader2 className="h-8 w-8 animate-spin opacity-60" />
            <p className="text-sm">─Éang tß║úi h├áng ─æß╗úi kiß╗âm duyß╗çtΓÇª</p>
          </div>
        ) : rows.length === 0 ? (
          <div className="flex h-64 flex-col items-center justify-center gap-2 text-muted-foreground">
            <Inbox className="h-12 w-12 opacity-40" />
            <p className="text-sm">Kh├┤ng c├│ sß╗▒ kiß╗çn n├áo trong mß╗Ñc n├áy.</p>
          </div>
        ) : (
          <div className="divide-y divide-border">
            {rows.map((event) => (
              <div key={event.id} className="flex flex-col gap-3 p-5 sm:flex-row sm:items-center">
                <div className="flex h-12 w-12 flex-shrink-0 items-center justify-center rounded-2xl gradient-primary text-lg font-bold text-white">
                  {event.title.charAt(0)}
                </div>

                <div className="min-w-0 flex-1 space-y-1">
                  <Link
                    href={`/dashboard/moderation/${event.id}`}
                    className="font-semibold text-foreground transition-colors hover:text-cyan-500"
                  >
                    {event.title}
                  </Link>
                  <div className="flex flex-wrap items-center gap-x-4 gap-y-1 text-xs text-muted-foreground">
                    <span className="flex items-center gap-1">
                      <Building2 className="h-3 w-3" />
                      {event.organizer}
                    </span>
                    <span className="flex items-center gap-1">
                      <MapPin className="h-3 w-3" />
                      {event.location}
                    </span>
                    <Badge variant="secondary" className="text-[11px]">
                      {event.category}
                    </Badge>
                  </div>
                  <p className="text-xs text-muted-foreground">
                    Gß╗¡i l├║c{" "}
                    {new Date(event.submittedAt).toLocaleDateString("vi-VN", {
                      day: "2-digit",
                      month: "2-digit",
                      year: "numeric",
                    })}
                  </p>
                </div>

                {/* Actions */}
                <div className="flex flex-shrink-0 items-center gap-2">
                  <Link
                    href={`/dashboard/moderation/${event.id}`}
                    title="Xem chi tiß║┐t hß╗ô s╞í"
                    className="inline-flex items-center gap-1.5 rounded-xl border border-border px-3.5 py-2 text-sm font-semibold text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
                  >
                    <Eye className="h-4 w-4" />
                    Chi tiß║┐t
                  </Link>
                  {event.status === "pending" ? (
                    <>
                      <button
                        onClick={() => approve(event.id)}
                        disabled={busyId === event.id}
                        className="inline-flex items-center gap-1.5 rounded-xl bg-emerald-600 px-3.5 py-2 text-sm font-semibold text-white transition-colors hover:bg-emerald-700 disabled:opacity-50 cursor-pointer"
                      >
                        {busyId === event.id ? <Loader2 className="h-4 w-4 animate-spin" /> : <Check className="h-4 w-4" />}
                        Duyß╗çt
                      </button>
                      <button
                        onClick={() => setRejectFor(event)}
                        disabled={busyId === event.id}
                        className="inline-flex items-center gap-1.5 rounded-xl border border-rose-200 px-3.5 py-2 text-sm font-semibold text-rose-600 transition-colors hover:bg-rose-50 disabled:opacity-50 cursor-pointer"
                      >
                        <X className="h-4 w-4" />
                        Tß╗½ chß╗æi
                      </button>
                    </>
                  ) : event.status === "waiting_deposit" ? (
                    <Badge variant="warning">Chß╗¥ cß╗ìc 20%</Badge>
                  ) : (
                    <Badge variant={event.status === "approved" ? "success" : "destructive"}>
                      {event.status === "approved" ? "─É├ú duyß╗çt" : "─É├ú tß╗½ chß╗æi"}
                    </Badge>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {rejectFor && (
        <ModerationDecisionModal
          mode="reject"
          eventTitle={rejectFor.title}
          onConfirm={confirmReject}
          onClose={() => setRejectFor(null)}
        />
      )}
    </div>
  )
}

"use client"

import { useCallback, useEffect, useMemo, useRef, useState } from "react"
import { Search, Inbox, ChevronLeft, ChevronRight, Loader2 } from "lucide-react"
import { cn } from "@/lib/utils"
import { NoticeModal } from "@/components/organizer/NoticeModal"
import { useOrganizerTitle } from "@/components/organizer/OrganizerShellContext"
import { MyEventCard } from "@/components/organizer/MyEventCard"
import type { OrganizerEvent, OrgEventStatus } from "@/components/organizer/my-events-data"
import { fetchMyEvents, submitForReview, payDeposit, payRemaining } from "@/components/organizer/organizer-my-events-api"
import styles from "./my-events.module.css"

const TABS = [
  { id: "upcoming", label: "Sß║»p tß╗¢i" },
  { id: "past", label: "─É├ú qua" },
  { id: "pending", label: "Chß╗¥ duyß╗çt" },
  { id: "waiting_deposit", label: "Chß╗¥ cß╗ìc" },
  { id: "draft", label: "Nh├íp" },
] as const

type TabId = OrgEventStatus
const PAGE_SIZE = 4

/** Organizer landing ("Sß╗▒ kiß╗çn cß╗ºa t├┤i"): live events from the API + search +
 *  status tabs + a "gß╗¡i duyß╗çt" action for drafts and rejected events. */
export default function MyEventsPage() {
  useOrganizerTitle("Sß╗▒ kiß╗çn cß╗ºa t├┤i")
  const [showNotice, setShowNotice] = useState(true)
  const [tab, setTab] = useState<TabId>("upcoming")
  const [query, setQuery] = useState("")
  const [page, setPage] = useState(1)

  const [events, setEvents] = useState<OrganizerEvent[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [submittingId, setSubmittingId] = useState<string | null>(null)
  const [payingDepositId, setPayingDepositId] = useState<string | null>(null)
  const [payingRemainingId, setPayingRemainingId] = useState<string | null>(null)

  // Roving focus for the status tablist (WAI-ARIA tabs keyboard pattern).
  const tabRefs = useRef<(HTMLButtonElement | null)[]>([])
  const onTabKeyDown = (e: React.KeyboardEvent, index: number) => {
    const keys = ["ArrowRight", "ArrowLeft", "Home", "End"]
    if (!keys.includes(e.key)) return
    e.preventDefault()
    const last = TABS.length - 1
    const next =
      e.key === "ArrowRight" ? (index + 1) % TABS.length
      : e.key === "ArrowLeft" ? (index - 1 + TABS.length) % TABS.length
      : e.key === "Home" ? 0
      : last
    setTab(TABS[next].id)
    tabRefs.current[next]?.focus()
  }

  const reload = useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      setEvents(await fetchMyEvents())
    } catch (err) {
      setError(err instanceof Error ? err.message : "Kh├┤ng tß║úi ─æ╞░ß╗úc danh s├ích sß╗▒ kiß╗çn")
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    void reload()
  }, [reload])

  const submit = async (id: string) => {
    setSubmittingId(id)
    setError(null)
    try {
      await submitForReview(id)
      await reload()
      setTab("pending") // event moves to the "Chß╗¥ duyß╗çt" tab
    } catch (err) {
      setError(err instanceof Error ? err.message : "Gß╗¡i duyß╗çt thß║Ñt bß║íi")
    } finally {
      setSubmittingId(null)
    }
  }

  const handlePayDeposit = async (id: string) => {
    setPayingDepositId(id)
    setError(null)
    try {
      await payDeposit(id)
      await reload()
      setTab("upcoming") // once deposit is paid, reviewStatus becomes PUBLISHED and status becomes upcoming
    } catch (err) {
      setError(err instanceof Error ? err.message : "Thanh to├ín cß╗ìc thß║Ñt bß║íi")
    } finally {
      setPayingDepositId(null)
    }
  }

  const handlePayRemaining = async (id: string) => {
    setPayingRemainingId(id)
    setError(null)
    try {
      await payRemaining(id)
      await reload()
    } catch (err) {
      setError(err instanceof Error ? err.message : "Thanh to├ín nß╗æt thß║Ñt bß║íi")
    } finally {
      setPayingRemainingId(null)
    }
  }

  // Events matching the active tab + search query.
  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase()
    return events.filter(
      (e) => e.status === tab && (q === "" || e.title.toLowerCase().includes(q))
    )
  }, [events, tab, query])

  // Reset to the first page whenever the filter changes.
  useEffect(() => setPage(1), [tab, query])

  const totalPages = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE))
  const current = Math.min(page, totalPages)
  const visible = filtered.slice((current - 1) * PAGE_SIZE, current * PAGE_SIZE)

  return (
    <>
      {showNotice && <NoticeModal onClose={() => setShowNotice(false)} />}

      <div className={styles.wrap}>
        <div className={styles.main}>
          <div className={styles.toolbar}>
            <form
              className={styles.search}
              role="search"
              onSubmit={(e) => e.preventDefault()}
            >
              <Search size={18} className={styles.searchIcon} aria-hidden="true" />
              <input
                className={styles.searchInput}
                type="search"
                placeholder="T├¼m kiß║┐m sß╗▒ kiß╗çn"
                aria-label="T├¼m kiß║┐m sß╗▒ kiß╗çn"
                value={query}
                onChange={(e) => setQuery(e.target.value)}
              />
              <button type="submit" className={styles.searchBtn}>
                T├¼m kiß║┐m
              </button>
            </form>

            <div className={styles.tabs} role="tablist" aria-label="Trß║íng th├íi sß╗▒ kiß╗çn">
              {TABS.map((t, i) => (
                <button
                  key={t.id}
                  ref={(el) => {
                    tabRefs.current[i] = el
                  }}
                  id={`my-events-tab-${t.id}`}
                  type="button"
                  role="tab"
                  aria-selected={tab === t.id}
                  aria-controls="my-events-panel"
                  tabIndex={tab === t.id ? 0 : -1}
                  className={cn(styles.tab, tab === t.id && styles.tabActive)}
                  onClick={() => setTab(t.id)}
                  onKeyDown={(e) => onTabKeyDown(e, i)}
                >
                  {t.label}
                </button>
              ))}
            </div>
          </div>

          <div
            id="my-events-panel"
            role="tabpanel"
            aria-labelledby={`my-events-tab-${tab}`}
            className={styles.panel}
          >

          {error && (
            <div className={cn(styles.notice, styles.noticeError)} role="alert">
              {error}
            </div>
          )}

          {/* Pending-approval notice (shown on the "Chß╗¥ duyß╗çt" tab) */}
          {tab === "pending" && filtered.length > 0 && (
            <div className={styles.notice} role="note">
              <span>
                <strong className={styles.noticeStrong}>L╞░u ├╜</strong>: Sß╗▒ kiß╗çn ─æang
                chß╗¥ duyß╗çt. ─Éß╗â ─æß║úm bß║úo t├¡nh bß║úo mß║¡t cho sß╗▒ kiß╗çn cß╗ºa bß║ín, quyß╗ün truy
                cß║¡p v├áo trang chß╗ë d├ánh cho chß╗º sß╗ƒ hß╗»u v├á quß║ún trß╗ï vi├¬n ─æ╞░ß╗úc ß╗ºy quyß╗ün.
              </span>
            </div>
          )}

          {loading ? (
            <div className={styles.empty}>
              <Loader2 size={48} className={styles.emptyIcon} style={{ animation: "spin 0.8s linear infinite" }} aria-hidden="true" />
              <p className={styles.emptyText}>─Éang tß║úi sß╗▒ kiß╗çn cß╗ºa bß║ínΓÇª</p>
            </div>
          ) : visible.length > 0 ? (
            <>
              <div className={styles.list}>
                {visible.map((event) => (
                  <MyEventCard
                    key={event.id}
                    event={event}
                    onSubmit={submit}
                    submitting={submittingId === event.id}
                    onPayDeposit={handlePayDeposit}
                    payingDeposit={payingDepositId === event.id}
                    onPayRemaining={handlePayRemaining}
                    payingRemaining={payingRemainingId === event.id}
                  />
                ))}
              </div>

              <nav className={styles.pager} aria-label="Ph├ón trang">
                <button
                  type="button"
                  className={styles.pageNav}
                  onClick={() => setPage(current - 1)}
                  disabled={current === 1}
                  aria-label="Trang tr╞░ß╗¢c"
                >
                  <ChevronLeft size={18} />
                </button>
                {Array.from({ length: totalPages }, (_, i) => i + 1).map((p) => (
                  <button
                    key={p}
                    type="button"
                    className={cn(styles.pageBtn, p === current && styles.pageBtnActive)}
                    aria-current={p === current ? "page" : undefined}
                    onClick={() => setPage(p)}
                  >
                    {p}
                  </button>
                ))}
                <button
                  type="button"
                  className={styles.pageNav}
                  onClick={() => setPage(current + 1)}
                  disabled={current === totalPages}
                  aria-label="Trang sau"
                >
                  <ChevronRight size={18} />
                </button>
              </nav>
            </>
          ) : (
            <div className={styles.empty}>
              <Inbox size={72} className={styles.emptyIcon} aria-hidden="true" />
              <p className={styles.emptyText}>Ch╞░a c├│ sß╗▒ kiß╗çn n├áo trong mß╗Ñc n├áy.</p>
            </div>
