            onClick={(e) => e.stopPropagation()}
          >
            <div className="mb-4 flex items-center justify-between">
              <h3 className="text-lg font-bold text-foreground">
                {editingId ? `Sß╗¡a ${title.toLowerCase()}` : `Th├¬m ${title.toLowerCase()}`}
              </h3>
              <button onClick={() => setForm(null)} className="text-muted-foreground hover:text-foreground cursor-pointer" aria-label="─É├│ng">
                <X className="h-5 w-5" />
              </button>
            </div>

            <div className="space-y-4">
              {fields.map((f) => (
                <FieldInput
                  key={f.key}
                  field={f}
                  value={form[f.key]}
                  onChange={(v) => setField(f.key, v)}
                  form={form}
                  setField={setField}
                />
              ))}
            </div>

            {formError && (
              <p role="alert" className="mt-3 text-sm text-rose-500">{formError}</p>
            )}

            <div className="mt-6 flex justify-end gap-2">
