              </button>
            </div>
          </div>
        </div>
      )}
    </>
  )
}

/** Render a table cell by field type. */
function CellValue({ type, value }: { type: FieldType; value: unknown }) {
  if (type === "image") {
    return value ? (
      // eslint-disable-next-line @next/next/no-img-element
      <img src={String(value)} alt="" className="h-10 w-16 rounded-md object-cover" />
    ) : (
      <span className="text-muted-foreground">ΓÇö</span>
    )
  }
  if (type === "emoji") return <span className="text-xl">{String(value ?? "")}</span>
  if (type === "boolean")
    return (
      <span
        className={`inline-flex rounded-full px-2 py-0.5 text-xs font-semibold ${
          value ? "bg-emerald-500/15 text-emerald-600" : "bg-muted text-muted-foreground"
        }`}
      >
        {value ? "C├│" : "Kh├┤ng"}
      </span>
    )
  const text = String(value ?? "")
  return <span className={text ? "" : "text-muted-foreground"}>{text || "ΓÇö"}</span>
}

/** Render a form input by field type. */
function FieldInput({
  field,
  value,
  onChange,
  form,
  setField,
}: {
  field: FieldConfig
  value: unknown
  onChange: (v: unknown) => void
  form?: FormState
  setField?: (key: string, value: unknown) => void
}) {
  const label = (
    <label className="mb-1 flex items-center gap-1 text-sm font-semibold text-foreground">
      {field.required && <span className="text-rose-500">*</span>}
      {field.label}
    </label>
  )
  const inputCls =
    "w-full rounded-xl border border-border bg-background px-3 py-2 text-sm text-foreground outline-none transition-colors focus:border-cyan-500"

  const [events, setEvents] = useState<any[]>([])
  const [loadingEvents, setLoadingEvents] = useState(false)

  useEffect(() => {
    if (field.type === "event-select") {
      setLoadingEvents(true)
      clientApi
        .get("/admin/events?limit=100&reviewStatus=PUBLISHED")
        .then((res: any) => {
          // Check structure: res or res.data. res is envelope, data property contains items
          const list = res.data ?? res
          setEvents(Array.isArray(list) ? list : [])
        })
        .catch(() => {})
        .finally(() => setLoadingEvents(false))
    }
  }, [field.type])

  if (field.type === "boolean") {
    return (
      <label className="flex items-center gap-2.5 text-sm text-foreground cursor-pointer">
        <input
          type="checkbox"
          className="h-5 w-5 accent-cyan-600"
          checked={!!value}
          onChange={(e) => onChange(e.target.checked)}
        />
        {field.label}
      </label>
    )
  }

  if (field.type === "event-select") {
    return (
      <div>
        {label}
        {loadingEvents ? (
          <div className="text-xs text-muted-foreground flex items-center gap-1.5 py-2">
            <Loader2 className="h-3 w-3 animate-spin text-cyan-500" /> ─Éang tß║úi danh s├ích sß╗▒ kiß╗çn ─æ├ú duyß╗çt...
          </div>
        ) : (
          <select
            className={inputCls}
            value={String(value ?? "")}
            onChange={(e) => {
              const selectedId = e.target.value
              onChange(selectedId)
              
              if (selectedId && setField) {
                const ev = events.find((item) => item._id === selectedId)
                if (ev) {
                  setField("title", ev.title)
                  const cleanDesc = (ev.description || "").replace(/<[^>]*>/g, "").slice(0, 120)
                  setField("subtitle", cleanDesc)
                  setField("imageUrl", ev.banner || ev.imageUrl || "")
                  setField("linkUrl", `/su-kien/${ev._id}`)
                }
              }
            }}
          >
            <option value="">-- Chß╗ìn sß╗▒ kiß╗çn quß║úng c├ío --</option>
            {events.map((ev) => (
              <option key={ev._id} value={ev._id}>
                {ev.title} ({ev.organizer || "BTC"})
              </option>
            ))}
          </select>
        )}
        {field.help && <p className="mt-1 text-xs text-muted-foreground">{field.help}</p>}
      </div>
    )
  }

  return (
    <div>
      {label}
      {field.type === "textarea" ? (
        <textarea
          rows={3}
          className={inputCls}
          placeholder={field.placeholder}
          value={String(value ?? "")}
          onChange={(e) => onChange(e.target.value)}
        />
      ) : (
        <input
          type={field.type === "number" ? "number" : "text"}
          className={inputCls}
          placeholder={field.placeholder}
          value={value === undefined || value === null ? "" : String(value)}
          onChange={(e) => onChange(e.target.value)}
        />
      )}
      {field.help && <p className="mt-1 text-xs text-muted-foreground">{field.help}</p>}
      {field.type === "image" && value ? (
        // eslint-disable-next-line @next/next/no-img-element
        <img src={String(value)} alt="" className="mt-2 h-24 w-full rounded-lg object-cover" />
      ) : null}
    </div>
  )
}

