      router.push("/ve-cua-toi");
    } catch (err) {
      setPayError(
        err instanceof Error ? err.message : "Thanh to├ín thß║Ñt bß║íi ΓÇö vui l├▓ng thß╗¡ lß║íi."
      );
      setPaying(false);
    }
  };

  return (
    <div className={styles.page}>
