            </div>
            <div className={styles.metaRow}>
              <MapPin size={17} className={styles.metaIcon} aria-hidden="true" />
              <span>{event.location}</span>
            </div>
          </div>

          <div className={styles.countdown}>
            <span className={styles.countdownLabel}>Ho├án tß║Ñt ─æß║╖t v├⌐ trong</span>
            <div className={`${styles.countdownClock} ${remaining <= 60 ? styles.countdownUrgent : ""}`}>
              <span className={styles.countdownBox}>{pad(minutes)}</span>
              <span className={styles.countdownColon}>:</span>
              <span className={styles.countdownBox}>{pad(seconds)}</span>
            </div>
          </div>
        </div>
      </header>

      <div className={styles.bodyWrap}>
        <h2 className={styles.sectionHeading}>THANH TO├üN</h2>
        <div className={styles.body}>
          {/* Left column */}
          <div className={styles.left}>
            <section className={styles.card}>
              <h3 className={styles.cardTitle}>Th├┤ng tin nhß║¡n v├⌐</h3>
              <p className={styles.receiveText}>
                V├⌐ ─æiß╗çn tß╗¡ sß║╜ ─æ╞░ß╗úc hiß╗ân thß╗ï trong mß╗Ñc <strong>&quot;V├⌐ cß╗ºa t├┤i&quot;</strong> cß╗ºa t├ái khoß║ún{" "}
                <span className={styles.email}>{user?.email ?? "t├ái khoß║ún cß╗ºa bß║ín"}</span>
