                <h3 className={styles.cardTitle}>Ph╞░╞íng thß╗⌐c thanh to├ín</h3>
                <ul className={styles.methodList}>
                  {PAYMENT_METHODS.map(({ id, label, Icon, tint }) => (
                    <li key={id}>
                      <label className={`${styles.method} ${method === id ? styles.methodActive : ""}`}>
                        <input
                          type="radio"
                          name="payment-method"
                          value={id}
                          checked={method === id}
                          onChange={() => setMethod(id)}
                          className={styles.radio}
                        />
                        <span className={styles.methodIcon} style={{ backgroundColor: tint }}>
                          <Icon size={16} aria-hidden="true" />
                        </span>
                        <span className={styles.methodLabel}>{label}</span>
                      </label>
                    </li>
                  ))}
                </ul>
              </section>
            )}
          </div>

          {/* Right column */}
          <aside className={styles.right}>
            <section className={styles.card}>
              <div className={styles.cardHeadRow}>
                <h3 className={styles.cardTitle}>Th├┤ng tin ─æß║╖t v├⌐</h3>
                <Link href={`/su-kien/${event.id}/dat-ve`} className={styles.linkBtn}>Chß╗ìn lß║íi v├⌐</Link>
              </div>
              <div className={styles.orderHead}>
                <span>Loß║íi v├⌐</span>
                <span>Sß╗æ l╞░ß╗úng</span>
