                  </div>
                  <div className={styles.orderQtyCol}>
                    <div className={styles.orderQty}>{pad(line.qty)}</div>
                    <div className={styles.orderSubtotal}>{formatVnd(line.subtotal)}</div>
                  </div>
                </div>
              ))}
            </section>

            <section className={styles.card}>
              <h3 className={styles.cardTitle}>Th├┤ng tin ─æ╞ín h├áng</h3>
              <div className={styles.summaryRow}>
                <span>Tß║ím t├¡nh</span>
                <span>{formatVnd(total)}</span>
              </div>
              <div className={styles.summaryDivider} />
              <div className={styles.totalRow}>
                <span>Tß╗òng tiß╗ün</span>
                <span className={styles.totalValue}>{formatVnd(total)}</span>
              </div>
              <p className={styles.terms}>
                Bß║▒ng viß╗çc tiß║┐n h├ánh ─æß║╖t mua, bß║ín ─æ├ú ─æß╗ông ├╜ vß╗¢i{" "}
                <a href="#" className={styles.termsLink}>─Éiß╗üu Kiß╗çn Giao Dß╗ïch Chung</a>
              </p>
              {payError && (
                <p role="alert" className={styles.terms} style={{ color: "#ef4444" }}>
                  {payError}
                </p>
              )}
              <button
                type="button"
                className={styles.payBtn}
                disabled={expired || paying}
                onClick={pay}
              >
                {expired
                  ? "Hß║┐t thß╗¥i gian giß╗» v├⌐"
                  : paying
                    ? "─Éang xß╗¡ l├╜ΓÇª"
                    : isFree
                      ? "─Éß║╖t v├⌐ miß╗àn ph├¡"
                      : "Thanh to├ín"}
              </button>
            </section>
          </aside>
        </div>
      </div>
    </div>
  );
}

