'use client';

import { useState, useEffect, useCallback } from 'react';
import styles from './HeroBanner.module.css';

const INTERVAL_MS = 5000;

export interface HeroBannerItem {
  id: string;
  title: string;
  subtitle: string;
  image: string;
  cta: string;
  link: string;
}

export default function HeroBanner({ banners }: { banners: HeroBannerItem[] }) {
  const [current, setCurrent] = useState(0);
  const [isPaused, setIsPaused] = useState(false);
  const [reducedMotion, setReducedMotion] = useState(false);
  const total = banners.length;

  const goTo = useCallback((index: number) => {
    setCurrent((index + total) % total);
  }, [total]);

  const goNext = useCallback(() => {
    goTo(current + 1);
  }, [current, goTo]);

  const goPrev = useCallback(() => {
    goTo(current - 1);
  }, [current, goTo]);

  /* Honour the user's reduced-motion preference */
  useEffect(() => {
    const mq = window.matchMedia('(prefers-reduced-motion: reduce)');
    const update = () => setReducedMotion(mq.matches);
    update();
    mq.addEventListener('change', update);
    return () => mq.removeEventListener('change', update);
  }, []);

  /* Auto-play ΓÇö paused on hover/focus and when motion is reduced */
  useEffect(() => {
    if (isPaused || reducedMotion || total <= 1) return;
    const timer = setInterval(goNext, INTERVAL_MS);
    return () => clearInterval(timer);
  }, [goNext, isPaused, reducedMotion, total]);

  if (total === 0) return null;

  return (
    <section
      className={styles.section}
      onMouseEnter={() => setIsPaused(true)}
      onMouseLeave={() => setIsPaused(false)}
      onFocusCapture={() => setIsPaused(true)}
      onBlurCapture={() => setIsPaused(false)}
      aria-roledescription="carousel"
      aria-label="Sß╗▒ kiß╗çn nß╗òi bß║¡t"
    >
      <div className={styles.container}>
        <div className={styles.banner}>
          {/* Slides */}
          <div className={styles.slideTrack}>
            {banners.map((banner, index) => (
              <div
                key={banner.id}
                className={`${styles.slide} ${index === current ? styles.slideActive : ''}`}
              >
                <a href={banner.link} className={styles.slideLink}>
                  <img
                    src={banner.image}
                    alt={banner.title}
                    className={styles.slideImage}
                    loading={index === 0 ? 'eager' : 'lazy'}
                  />
                  <div className={styles.overlay} />
                  <div className={styles.content}>
                    <h2 className={styles.title}>{banner.title}</h2>
                    <p className={styles.subtitle}>{banner.subtitle}</p>
                    <span className={styles.ctaButton}>
                      {banner.cta}
                    </span>
                  </div>
                </a>
              </div>
            ))}
          </div>

          {/* Left Arrow */}
          <button
            className={`${styles.arrowBtn} ${styles.arrowBtnLeft}`}
            onClick={goPrev}
            aria-label="Slide tr╞░ß╗¢c"
          >
            <svg className={styles.arrowIcon} viewBox="0 0 24 24">
              <polyline points="15 18 9 12 15 6" />
            </svg>
          </button>

          {/* Right Arrow */}
          <button
            className={`${styles.arrowBtn} ${styles.arrowBtnRight}`}
            onClick={goNext}
            aria-label="Slide tiß║┐p theo"
          >
            <svg className={styles.arrowIcon} viewBox="0 0 24 24">
              <polyline points="9 6 15 12 9 18" />
            </svg>
          </button>

          {/* Dot Indicators */}
          <div className={styles.dots}>
            {banners.map((_, index) => (
              <button
                key={index}
                className={`${styles.dot} ${index === current ? styles.dotActive : ''}`}
                onClick={() => goTo(index)}
                aria-label={`─Éi tß╗¢i slide ${index + 1}`}
              />
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}

