/**
 * Maps the wizard's CreateEventForm to the backend organizer API and saves it:
 *  1. uploads local previews (banner/poster/logo/ticket art ΓåÆ /api/uploads/images,
 *     hand-drawn signature ΓåÆ /api/uploads/signatures),
 *  2. POST /api/organizer/events (create) or PUT + bulk ticket configure (re-save).
 * Permit documents are uploaded on selection (LogisticsPermitStep) and arrive
 * here already carrying their /uploads/permits/... URL.
 */
import { clientApi } from "@/lib/client-api"
import { slugify, type CreateEventForm, type EventShow, type TicketType } from "./create-event-data"

const MONGO_ID = /^[0-9a-f]{24}$/i

export interface SavedEventResult {
  eventId: string
  /** FE show id ΓåÆ server show id, computed from the exact set that was sent. */
  showIdMap: { feShowId: string; serverId: string }[]
  /** Uploaded /uploads URLs to merge back into the form so re-saves don't
   *  re-upload the same assets (and the signature URL stays stable). */
  assetPatch: Partial<CreateEventForm>
}

/** Upload a local preview (blob:/data: URL) and return the stored /uploads URL. */
async function uploadLocalFile(
  kind: "images" | "signatures",
  src: string,
  baseName: string
): Promise<string> {
  if (src.startsWith("/uploads/")) return src // already stored on the server
  const blob = await fetch(src).then((r) => r.blob())
  const ext = blob.type === "image/jpeg" ? "jpg" : blob.type === "image/webp" ? "webp" : "png"
  const formData = new FormData()
  formData.append("file", blob, `${baseName}.${ext}`)
  const res = await fetch(`/api/uploads/${kind}`, {
    method: "POST",
    body: formData,
    credentials: "include",
  })
  const json = await res.json().catch(() => ({}))
  if (!res.ok || !json?.data?.url) {
    throw new Error(json?.message || "Tß║úi file l├¬n thß║Ñt bß║íi ΓÇö vui l├▓ng thß╗¡ lß║íi")
  }
  return json.data.url as string
}

/** FE-side gate mirroring the BE rules, with friendly Vietnamese messages. */
function validateForm(form: CreateEventForm): void {
  if (!form.name.trim()) throw new Error("Vui l├▓ng nhß║¡p t├¬n sß╗▒ kiß╗çn (b╞░ß╗¢c 1)")
  if (!form.bannerImage) throw new Error("Vui l├▓ng tß║úi ß║únh nß╗ün sß╗▒ kiß╗çn (b╞░ß╗¢c 1)")
  if (!form.category) throw new Error("Vui l├▓ng chß╗ìn thß╗â loß║íi sß╗▒ kiß╗çn (b╞░ß╗¢c 1)")
  if (form.locationType === "offline") {
    if (!form.venueName.trim() || !form.province || !form.ward || !form.street.trim()) {
      throw new Error(
        "Vui l├▓ng nhß║¡p ─æß╗º ─æß╗ïa ─æiß╗âm: t├¬n ─æß╗ïa ─æiß╗âm, tß╗ënh/th├ánh, ph╞░ß╗¥ng/x├ú, sß╗æ nh├á & ─æ╞░ß╗¥ng (b╞░ß╗¢c 1)"
      )
    }
  } else if (!form.street.trim()) {
    throw new Error("Vui l├▓ng nhß║¡p link tham gia sß╗▒ kiß╗çn online (b╞░ß╗¢c 1)")
  }
  const validShows = form.shows.filter((s) => s.startTime && s.endTime)
  if (validShows.length === 0) {
    throw new Error("Vui l├▓ng th├¬m ├¡t nhß║Ñt 1 suß║Ñt diß╗àn vß╗¢i thß╗¥i gian bß║»t ─æß║ºu/kß║┐t th├║c (b╞░ß╗¢c 2)")
  }
  if (validShows.flatMap((s) => s.tickets).length === 0) {
    throw new Error("Vui l├▓ng tß║ío ├¡t nhß║Ñt 1 loß║íi v├⌐ (b╞░ß╗¢c 2)")
  }
  if (form.contractAgreed && !form.signatureDataUrl) {
    throw new Error("Vui l├▓ng k├╜ t├¬n tr╞░ß╗¢c khi ─æß╗ông ├╜ hß╗úp ─æß╗ông (b╞░ß╗¢c 5)")
  }
}

/** datetime-local string ΓåÆ ISO, silently dropped when unparseable. */
function toIso(value: string): string | undefined {
  if (!value) return undefined
  const d = new Date(value)
  return Number.isNaN(d.getTime()) ? undefined : d.toISOString()
}

async function mapTicket(t: TicketType) {
  return {
    ticketName: t.name,
    price: t.isFree ? 0 : t.price,
    quantity: t.quantity,
    minPerOrder: t.minPerOrder,
    maxPerOrder: t.maxPerOrder,
    description: t.description || undefined,
    image: t.image ? await uploadLocalFile("images", t.image, "ve") : undefined,
    saleStart: toIso(t.saleStart),
    saleEnd: toIso(t.saleEnd),
  }
}

async function buildPayload(form: CreateEventForm) {
  const banner = await uploadLocalFile("images", form.bannerImage!, "anh-nen")
  const posterImage = form.posterImage
    ? await uploadLocalFile("images", form.posterImage, "poster")
    : undefined
  const orgLogo = form.orgLogo ? await uploadLocalFile("images", form.orgLogo, "logo") : undefined
  const signatureUrl = form.signatureDataUrl
    ? await uploadLocalFile("signatures", form.signatureDataUrl, "chu-ky")
    : undefined

  // Everything below works on this snapshot ΓÇö the same filtered list drives
  // the payload, the capacity sum and the FEΓåöserver show-id mapping.
  const sentShows: EventShow[] = form.shows.filter((s) => s.startTime && s.endTime)

  const shows = await Promise.all(
    sentShows.map(async (s) => ({
      // Only real server ids ride along; FE-generated ids mean "new show".
      _id: MONGO_ID.test(s.id) ? s.id : undefined,
      title: s.title.trim() || undefined,
      startTime: new Date(s.startTime).toISOString(),
      endTime: new Date(s.endTime).toISOString(),
      tickets: await Promise.all(s.tickets.map(mapTicket)),
    }))
  )

  // No explicit capacity field in the wizard ΓÇö derive from the inventory
  // actually being sent.
  const capacity = Math.max(
    1,
    sentShows.flatMap((s) => s.tickets).reduce((sum, t) => sum + (t.quantity || 0), 0)
  )

  // Merged into the form after a successful save: previews switch from
  // blob:/data: to the stored URLs, so re-saves skip re-uploading.
  const assetPatch: Partial<CreateEventForm> = {
    bannerImage: banner,
    ...(posterImage ? { posterImage } : {}),
    ...(orgLogo ? { orgLogo } : {}),
    ...(signatureUrl ? { signatureDataUrl: signatureUrl } : {}),
  }

  return {
    sentShowIds: sentShows.map((s) => s.id),
    assetPatch,
    payload: {
      title: form.name.trim(),
      description: form.description,
      categoryId: form.category,
      capacity,
      banner,
      posterImage,
      locationType: form.locationType,
      ...(form.locationType === "offline"
        ? {
            venue: {
              name: form.venueName.trim(),
              province: form.province,
              ward: form.ward,
              street: form.street.trim(),
            },
          }
        : { location: form.street.trim() }),
      orgName: form.orgName.trim() || undefined,
      orgLogo,
      orgInfo: form.orgInfo.trim() || undefined,
      shows,
      // Send exactly what the settings step previews (slugified form).
      slug: slugify(form.slug.trim()) || undefined,
      privacy: form.privacy,
      confirmationMessage: form.confirmationMessage.trim() || undefined,
      logisticsServices: form.logisticsServices,
      permitDocuments: form.permitDocuments.map((d) => ({
        name: d.name,
        url: d.url,
        sizeKb: d.sizeKb,
      })),
      ...(form.contractRepName.trim() || form.contractAgreed
        ? {
            contract: {
              repName: form.contractRepName.trim() || undefined,
              agreed: form.contractAgreed,
              signatureUrl,
            },
          }
        : {}),
      ...(form.bankName || form.bankAccountNumber || form.bankAccountHolder
        ? {
            paymentInfo: {
              bankName: form.bankName || undefined,
              accountNumber: form.bankAccountNumber || undefined,
              accountHolder: form.bankAccountHolder.trim() || undefined,
            },
          }
        : {}),
    },
  }
}

interface ApiEnvelope<T> {
  success: boolean
  message: string
  data: T
}

interface ServerShow {
  _id: string
}

/**
 * Save the wizard as a DRAFT event. First save POSTs everything in one call;
 * re-saves PUT the event (shows without tickets) then bulk-replace the ticket
 * set per show ΓÇö draft-only, so full replacement is safe.
 */
export async function saveEventDraft(
  form: CreateEventForm,
  eventId?: string
): Promise<SavedEventResult> {
  validateForm(form)
  const { sentShowIds, assetPatch, payload } = await buildPayload(form)

  // The server persists shows in submitted order, so index i of the response
  // corresponds to sentShowIds[i] ΓÇö mapped back by FE id, never by position
  // in the (possibly larger, blank-row-containing) form.shows array.
  const toShowIdMap = (serverShows: ServerShow[]) =>
    sentShowIds.map((feShowId, i) => ({ feShowId, serverId: serverShows[i]?._id ?? feShowId }))

  if (!eventId) {
    const res = await clientApi.post<
      ApiEnvelope<{ event: { _id: string; shows: ServerShow[] } }>
    >("/organizer/events", payload)
    return {
      eventId: res.data.event._id,
      showIdMap: toShowIdMap(res.data.event.shows ?? []),
      assetPatch,
    }
  }

  const { shows, ...eventFields } = payload
  const updated = await clientApi.put<ApiEnvelope<{ _id: string; shows: ServerShow[] }>>(
    `/organizer/events/${eventId}`,
    { ...eventFields, shows: shows.map(({ tickets: _tickets, ...times }) => times) }
  )
  const serverShows = updated.data.shows ?? []

  // Bulk ticket configuration: rows map onto the saved shows by index.
  const ticketRows = shows.flatMap((s, i) =>
    s.tickets.map((t) => ({ ...t, showId: serverShows[i]?._id }))
  )
  await clientApi.put(`/organizer/events/${eventId}/tickets`, { tickets: ticketRows })

  return { eventId, showIdMap: toShowIdMap(serverShows), assetPatch }
}

"use client"

import { useEffect, useState } from "react"
import { Save, PlusCircle, Trash2, AlertTriangle, CheckCircle2, Ticket, Info } from "lucide-react"
import { cn } from "@/lib/utils"
import type { ServerEventShow } from "../organizer-event-detail-api"
import { updateEventShows, type ScheduleShowInput } from "./organizer-schedule-api"
import tableStyles from "../checkin/checkin.module.css"
import styles from "./schedule.module.css"

/** ISO (UTC) ΓåÆ "YYYY-MM-DDTHH:mm" in the browser's local time, for datetime-local. */
function isoToLocalInput(iso?: string): string {
  if (!iso) return ""
  const d = new Date(iso)
  if (Number.isNaN(d.getTime())) return ""
  const pad = (n: number) => String(n).padStart(2, "0")
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`
}

/** One editable row of the show table. */
interface ShowRow {
  /** Server _id for saved shows; FE-generated key for new rows. */
  key: string
  serverId?: string
  title: string
  start: string
  end: string
}

let rowSeq = 0
function newRow(): ShowRow {
  rowSeq += 1
  return { key: `new-${rowSeq}`, title: "", start: "", end: "" }
}

function toRows(shows: ServerEventShow[]): ShowRow[] {
  return shows
    .filter((s) => s._id)
    .map((s) => ({
      key: s._id as string,
      serverId: s._id,
      title: s.title ?? "",
      start: isoToLocalInput(s.startTime),
      end: isoToLocalInput(s.endTime),
    }))
}

interface ScheduleManagementViewProps {
  eventId: string
  /** Saved shows from the workspace detail. */
  shows: ServerEventShow[]
  /** Ticket-tier count per show id ΓÇö a show with tiers can't be deleted. */
  ticketCounts: Record<string, number>
  /** Backend review state ΓÇö schedule is editable only while DRAFT/REJECTED. */
  reviewStatus?: string
  /** Called after a successful save so the shared workspace context (read by
   *  sibling tabs like "Chß╗ënh sß╗¡a" and the "─Éß╗òi suß║Ñt diß╗àn" switcher)
   *  refetches instead of serving what it loaded on its own first mount. */
  onSaved?: () => void
}

/**
 * "Lß╗ïch tr├¼nh" screen: the event's shows (suß║Ñt diß╗àn) ΓÇö add, rename, re-time
 * or remove showings. Ticket tiers are attached to a show on the "Chß╗ënh sß╗¡a"
 * tab; a show that still has tiers must be emptied there before it can be
 * removed here (the backend enforces the same rule).
 */
export function ScheduleManagementView({
  eventId,
  shows,
  ticketCounts,
  reviewStatus,
  onSaved,
}: ScheduleManagementViewProps) {
  const [rows, setRows] = useState<ShowRow[]>(() => {
    const initial = toRows(shows)
    return initial.length > 0 ? initial : [newRow()]
  })
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [success, setSuccess] = useState<string | null>(null)

  // Keep the table in sync when the workspace event reloads (e.g. after a
  // save on the "Chß╗ënh sß╗¡a" tab changed the schedule too).
  useEffect(() => {
    const next = toRows(shows)
    setRows(next.length > 0 ? next : [newRow()])
  }, [shows])

  const editable = reviewStatus === "DRAFT" || reviewStatus === "REJECTED"

  const patchRow = (key: string, patch: Partial<ShowRow>) => {
    setSuccess(null)
    setRows((prev) => prev.map((r) => (r.key === key ? { ...r, ...patch } : r)))
  }

  const removeRow = (key: string) => {
    setSuccess(null)
    setRows((prev) => prev.filter((r) => r.key !== key))
  }

  /** Mirror the backend rules for a friendly message before the request goes out. */
  function validate(): string | null {
    if (rows.length === 0) return "Sß╗▒ kiß╗çn cß║ºn ├¡t nhß║Ñt 1 suß║Ñt diß╗àn."
    for (let i = 0; i < rows.length; i += 1) {
      const r = rows[i]
      const label = r.title.trim() || `Suß║Ñt ${i + 1}`
      if (!r.start || !r.end) return `${label}: vui l├▓ng nhß║¡p ─æß╗º thß╗¥i gian bß║»t ─æß║ºu v├á kß║┐t th├║c.`
      const s = new Date(r.start).getTime()
      const e = new Date(r.end).getTime()
      if (Number.isNaN(s) || Number.isNaN(e)) return `${label}: thß╗¥i gian kh├┤ng hß╗úp lß╗ç.`
      if (e <= s) return `${label}: thß╗¥i gian kß║┐t th├║c phß║úi sau thß╗¥i gian bß║»t ─æß║ºu.`
      if (s <= Date.now()) return `${label}: thß╗¥i gian bß║»t ─æß║ºu phß║úi ß╗ƒ t╞░╞íng lai.`
    }
    return null
  }

  const save = async () => {
    setError(null)
    setSuccess(null)
    const msg = validate()
    if (msg) {
      setError(msg)
      return
    }
    setSaving(true)
    try {
      const payload: ScheduleShowInput[] = rows.map((r) => ({
        _id: r.serverId,
        title: r.title.trim() || undefined,
        startTime: new Date(r.start).toISOString(),
        endTime: new Date(r.end).toISOString(),
      }))
      const saved = await updateEventShows(eventId, payload)
      setRows(saved.length > 0 ? toRows(saved) : [newRow()])
      setSuccess("─É├ú l╞░u lß╗ïch tr├¼nh suß║Ñt diß╗àn.")
      onSaved?.()
    } catch (e) {
      setError(e instanceof Error ? e.message : "L╞░u lß╗ïch tr├¼nh thß║Ñt bß║íi")
    } finally {
      setSaving(false)
    }
  }

  return (
    <div>
      <h1 className={tableStyles.pageHeading}>Lß╗ïch tr├¼nh suß║Ñt diß╗àn</h1>
      <p className={styles.intro}>
        Mß╗Öt sß╗▒ kiß╗çn c├│ thß╗â gß╗ôm nhiß╗üu suß║Ñt diß╗àn, mß╗ùi suß║Ñt c├│ thß╗¥i gian ri├¬ng v├á c├íc loß║íi v├⌐
        ri├¬ng. Loß║íi v├⌐ ─æ╞░ß╗úc gß║»n v├áo tß╗½ng suß║Ñt ß╗ƒ tab &quot;Chß╗ënh sß╗¡a&quot;.
      </p>

      {!editable && (
        <div className={cn(styles.notice, styles.noticeWarn)} role="status">
          <AlertTriangle size={18} aria-hidden="true" />
          <span>
            Lß╗ïch tr├¼nh chß╗ë chß╗ënh sß╗¡a ─æ╞░ß╗úc khi sß╗▒ kiß╗çn ß╗ƒ trß║íng th├íi <b>Nh├íp</b> hoß║╖c <b>Bß╗ï tß╗½ chß╗æi</b>.
            {reviewStatus ? ` Hiß╗çn tß║íi: ${reviewStatus}.` : ""}
          </span>
        </div>
      )}

      <div className={styles.showList}>
        {rows.map((row, i) => {
          const tierCount = row.serverId ? ticketCounts[row.serverId] ?? 0 : 0
          return (
            <div key={row.key} className={styles.showRow}>
              <div className={styles.rowHead}>
                <input
                  type="text"
                  className={cn(styles.input, styles.titleInput)}
                  value={row.title}
                  maxLength={100}
                  placeholder={`Suß║Ñt ${i + 1}`}
                  disabled={!editable}
                  aria-label="T├¬n suß║Ñt diß╗àn"
                  onChange={(e) => patchRow(row.key, { title: e.target.value })}
                />
                <span className={cn(styles.badge, row.serverId ? styles.badgeSaved : styles.badgeNew)}>
                  {row.serverId ? "─É├ú l╞░u" : "Mß╗¢i"}
                </span>
                <span className={styles.ticketCount} title="Sß╗æ loß║íi v├⌐ thuß╗Öc suß║Ñt n├áy">
                  <Ticket size={14} aria-hidden="true" /> {tierCount} loß║íi v├⌐
                </span>
                {editable && (
                  <button
                    type="button"
                    className={styles.iconBtn}
                    onClick={() => removeRow(row.key)}
                    disabled={tierCount > 0}
                    title={
                      tierCount > 0
                        ? "Suß║Ñt n├áy c├▓n loß║íi v├⌐ ΓÇö xo├í/chuyß╗ân v├⌐ ß╗ƒ tab Chß╗ënh sß╗¡a tr╞░ß╗¢c"
                        : "X├│a suß║Ñt diß╗àn"
                    }
                    aria-label="X├│a suß║Ñt diß╗àn"
                  >
                    <Trash2 size={16} />
                  </button>
                )}
              </div>
              <div className={styles.dateFields}>
                <div>
                  <label className={styles.fieldLabel} htmlFor={`show-start-${row.key}`}>
                    Thß╗¥i gian bß║»t ─æß║ºu
                  </label>
                  <input
                    id={`show-start-${row.key}`}
                    type="datetime-local"
                    className={styles.input}
                    value={row.start}
                    disabled={!editable}
                    onChange={(e) => patchRow(row.key, { start: e.target.value })}
                  />
                </div>
                <div>
                  <label className={styles.fieldLabel} htmlFor={`show-end-${row.key}`}>
                    Thß╗¥i gian kß║┐t th├║c
                  </label>
                  <input
                    id={`show-end-${row.key}`}
                    type="datetime-local"
                    className={styles.input}
                    value={row.end}
                    min={row.start || undefined}
                    disabled={!editable}
                    onChange={(e) => patchRow(row.key, { end: e.target.value })}
                  />
                </div>
              </div>
            </div>
          )
        })}
      </div>

      {editable && (
        <p className={styles.hint}>
          <Info size={14} aria-hidden="true" />
          Xo├í mß╗Öt suß║Ñt ─æ├ú c├│ loß║íi v├⌐: sang tab &quot;Chß╗ënh sß╗¡a&quot; xo├í hoß║╖c chuyß╗ân c├íc v├⌐ cß╗ºa suß║Ñt ─æ├│ tr╞░ß╗¢c.
        </p>
      )}

      {error && (
        <p role="alert" className={cn(styles.notice, styles.noticeError)}>
          <AlertTriangle size={18} aria-hidden="true" />
          <span>{error}</span>
        </p>
      )}
      {success && (
        <p role="status" className={cn(styles.notice, styles.noticeOk)}>
          <CheckCircle2 size={18} aria-hidden="true" />
          <span>{success}</span>
        </p>
      )}

      {editable && (
        <div className={styles.actions}>
          <button
            type="button"
            className={styles.secondaryBtn}
            onClick={() => {
              setSuccess(null)
              setRows((prev) => [...prev, newRow()])
            }}
            disabled={saving}
          >
            <PlusCircle size={16} aria-hidden="true" /> Th├¬m suß║Ñt diß╗àn
          </button>
          <button type="button" className={styles.primaryBtn} onClick={save} disabled={saving}>
            <Save size={16} aria-hidden="true" /> {saving ? "─Éang l╞░uΓÇª" : "L╞░u lß╗ïch tr├¼nh"}
          </button>
        </div>
      )}
    </div>
  )
}

"use client"

import { useCallback, useEffect, useMemo, useRef, useState } from "react"
import { CalendarDays, Search, UserCheck, Users, Loader2, AlertCircle, CheckCircle2 } from "lucide-react"
import { cn } from "@/lib/utils"
import { Badge } from "@/components/ui/badge"
import { clientApi } from "@/lib/client-api"
import {
  fetchEventAssignments,
  createAssignment,
  updateAssignmentNote,
  deleteAssignment,
  type StaffAssignment,
} from "@/lib/staff-api"
import { fetchAdminEvents, type AdminEvent } from "@/lib/admin-event-api"

// ΓöÇΓöÇΓöÇ Types ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

interface StaffUser {
  _id: string
  fullName: string
  email: string
  phone?: string
  role: string
  accountStatus: string
}

interface ApiEnvelope<T> {
  success: boolean
  message: string
  data: T
  meta?: { currentPage: number; totalPages: number; totalItems: number; itemsPerPage: number }
}

// ΓöÇΓöÇΓöÇ Component ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export function StaffAssignmentView() {
  // State: events
  const [events, setEvents] = useState<AdminEvent[]>([])
  const [eventsLoading, setEventsLoading] = useState(true)

  // State: staff users
  const [staffUsers, setStaffUsers] = useState<StaffUser[]>([])
  const [staffLoading, setStaffLoading] = useState(true)

  // State: current event + assignments
  const [selectedEventId, setSelectedEventId] = useState<string>("")
  const [assignments, setAssignments] = useState<StaffAssignment[]>([])
  const [assignmentsLoading, setAssignmentsLoading] = useState(false)

  // State: in-progress ops (staffId ΓåÆ loading)
  const [toggling, setToggling] = useState<Record<string, boolean>>({})
  const [savingNotes, setSavingNotes] = useState<Record<string, boolean>>({})
  const savedNotesRef = useRef<Record<string, string>>({})

  // State: search + feedback
  const [query, setQuery] = useState("")
  const [toast, setToast] = useState<{ msg: string; ok: boolean } | null>(null)

  // ΓöÇΓöÇ Fetch events ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

  useEffect(() => {
    fetchAdminEvents({ status: "published", limit: 100 })
      .then(({ events: ev }) => {
        setEvents(ev)
        if (ev.length > 0) setSelectedEventId(ev[0]._id)
      })
      .catch(console.error)
      .finally(() => setEventsLoading(false))
  }, [])

  // ΓöÇΓöÇ Fetch staff users ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

  useEffect(() => {
    clientApi
      .get<ApiEnvelope<StaffUser[]>>("/users/admin?role=STAFF&limit=200")
      .then((res) => setStaffUsers(res.data ?? []))
      .catch(console.error)
      .finally(() => setStaffLoading(false))
  }, [])

  // ΓöÇΓöÇ Fetch assignments for selected event ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

  const loadAssignments = useCallback(async (eventId: string) => {
    if (!eventId) return
    setAssignmentsLoading(true)
    try {
      const data = await fetchEventAssignments(eventId)
      setAssignments(data)
      savedNotesRef.current = Object.fromEntries(
        data.map((assignment) => [assignment._id, assignment.note ?? ""])
      )
    } catch {
      setAssignments([])
    } finally {
      setAssignmentsLoading(false)
    }
  }, [])

  useEffect(() => {
    if (selectedEventId) loadAssignments(selectedEventId)
  }, [selectedEventId, loadAssignments])

  // ΓöÇΓöÇ Derived data ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

  const filteredStaff = useMemo(() => {
    const q = query.trim().toLowerCase()
    if (!q) return staffUsers
    return staffUsers.filter((s) =>
      [s.fullName, s.email, s.phone ?? ""].some((v) => v.toLowerCase().includes(q))
    )
  }, [staffUsers, query])

  const selectedEvent = events.find((e) => e._id === selectedEventId)

  // Helper: find existing assignment for a staff member
  const getAssignment = (staffId: string) =>
    assignments.find(
      (a) =>
        (typeof a.staffId === "string" ? a.staffId : a.staffId._id) === staffId
    )

  // ΓöÇΓöÇ Toggle assign / unassign ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

  const toggleStaff = async (staffId: string) => {
    if (!selectedEventId || toggling[staffId]) return
    setToggling((p) => ({ ...p, [staffId]: true }))

    const existing = getAssignment(staffId)
    try {
      if (existing) {
        // Unassign
        await deleteAssignment(selectedEventId, existing._id)
        setAssignments((prev) => prev.filter((a) => a._id !== existing._id))
        delete savedNotesRef.current[existing._id]
        showToast("─É├ú hß╗ºy ph├ón c├┤ng", true)
      } else {
        // Ph├ón c├┤ng tr╞░ß╗¢c; admin c├│ thß╗â nhß║¡p ghi ch├║ nhiß╗çm vß╗Ñ ngay sau ─æ├│.
        const newA = await createAssignment(selectedEventId, {
          staffId,
          note: "",
        })
        setAssignments((prev) => [...prev, newA])
        savedNotesRef.current[newA._id] = newA.note ?? ""
        showToast("Ph├ón c├┤ng th├ánh c├┤ng!", true)
      }
    } catch (err: any) {
      showToast(err.message ?? "Lß╗ùi khi thß╗▒c hiß╗çn ph├ón c├┤ng", false)
    } finally {
      setToggling((p) => ({ ...p, [staffId]: false }))
    }
  }

  const changeNote = (assignmentId: string, note: string) => {
    setAssignments((prev) =>
      prev.map((assignment) =>
        assignment._id === assignmentId ? { ...assignment, note } : assignment
      )
    )
  }

  const saveNote = async (staffId: string, note: string) => {
    const existing = getAssignment(staffId)
    if (!existing || toggling[staffId] || savingNotes[staffId]) return

    const normalizedNote = note.trim()
    if (normalizedNote === (savedNotesRef.current[existing._id] ?? "")) {
      if (normalizedNote !== note) changeNote(existing._id, normalizedNote)
      return
    }

    setSavingNotes((prev) => ({ ...prev, [staffId]: true }))
    try {
      const updated = await updateAssignmentNote(
        selectedEventId,
        existing._id,
        normalizedNote
      )
      savedNotesRef.current[existing._id] = updated.note ?? ""
      setAssignments((prev) =>
        prev.map((assignment) =>
          assignment._id === existing._id ? updated : assignment
        )
      )
      showToast("─É├ú l╞░u ghi ch├║ nhiß╗çm vß╗Ñ", true)
    } catch (err: any) {
      changeNote(existing._id, savedNotesRef.current[existing._id] ?? "")
      showToast(err.message ?? "Kh├┤ng thß╗â l╞░u ghi ch├║ nhiß╗çm vß╗Ñ", false)
    } finally {
      setSavingNotes((prev) => ({ ...prev, [staffId]: false }))
    }
  }

  const showToast = (msg: string, ok: boolean) => {
    setToast({ msg, ok })
    setTimeout(() => setToast(null), 3000)
  }

  // ΓöÇΓöÇ Render ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

  const isLoading = eventsLoading || staffLoading

  return (
    <div className="space-y-6 animate-fade-up">
      <div>
        <h2 className="text-2xl font-bold text-foreground">Ph├ón c├┤ng staff</h2>
        <p className="mt-1 text-sm text-muted-foreground">
          G├ín nh├ón vi├¬n check-in v├áo sß╗▒ kiß╗çn v├á ghi ch├║ nhiß╗çm vß╗Ñ cß║ºn thß╗▒c hiß╗çn.
        </p>
      </div>

      {/* Toast */}
      {toast && (
        <div
          className={cn(
            "fixed bottom-6 right-6 z-50 flex items-center gap-2 rounded-xl px-4 py-3 text-sm font-semibold shadow-lg",
            toast.ok
              ? "bg-emerald-600 text-white"
              : "bg-destructive text-destructive-foreground"
          )}
        >
          {toast.ok ? <CheckCircle2 size={16} /> : <AlertCircle size={16} />}
          {toast.msg}
        </div>
      )}

      {isLoading ? (
        <div className="flex items-center justify-center py-16">
          <Loader2 className="animate-spin text-primary" size={32} />
        </div>
      ) : (
        <div className="grid gap-6 lg:grid-cols-[1fr_1.6fr]">
          {/* ΓöÇΓöÇ Event list ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
          <div className="space-y-2">
