"use client"

import { useCallback, useEffect, useRef, useState } from "react"
import { CalendarClock, MapPin, CheckCircle2, Clock, Ticket, type LucideIcon, Loader2 } from "lucide-react"
import { cn } from "@/lib/utils"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/Card"
import { CheckInScanner } from "./CheckInScanner"
import { CheckInProgressRing } from "./CheckInProgressRing"
import type { CheckInResult } from "./staff-checkin-data"
import {
  checkInTicket,
  fetchCheckInStats,
  type CheckInStats,
  type CheckInResult as ApiCheckInResult,
  type CheckInResponse,
} from "@/lib/staff-api"

// Re-use the existing CheckInResult type shape for scanner feedback
type ScanResult = CheckInResult | null

/** Map API response ΓåÆ legacy CheckInResult shape that CheckInScanner expects */
function formatScanTime(value?: string): string | null {
  if (!value) return null
  return new Date(value).toLocaleTimeString("vi-VN", {
    hour: "2-digit",
    minute: "2-digit",
  })
}

function mapToScannerResult(response: CheckInResponse, code: string): CheckInResult {
  const statusMap: Record<ApiCheckInResult, CheckInResult["status"]> = {
    success: "success",
    duplicate: "duplicate",
    invalid: "invalid",
    wrong_event: "invalid",
    cancelled: "invalid",
  }
  const status = statusMap[response.result] ?? "invalid"
  if (status === "invalid") return { status }

  return {
    status,
    ticket: {
      code: code.trim().toUpperCase(),
      attendeeName: response.attendeeName ?? "Ng╞░ß╗¥i tham dß╗▒",
      email: "",
      orderCode: "",
      ticketType: response.ticketName ?? "V├⌐ sß╗▒ kiß╗çn",
      checkedInAt: formatScanTime(response.checkedInAt),
    },
    previousTime: formatScanTime(response.previousCheckedInAt) ?? undefined,
  }
}

const POLL_INTERVAL_MS = 15_000 // Refresh stats every 15s

/**
 * Staff check-in station for one assigned event.
 * Replaces mock data with real API calls:
 *  - POST /api/staff/check-in   ΓåÆ scan a ticket
 *  - GET  /api/staff/events/:id/checkin-stats ΓåÆ live counters
 */
export function StaffCheckInView({ eventId }: { eventId: string }) {
  const checkingRef = useRef(false)
  const [stats, setStats] = useState<CheckInStats | null>(null)
  const [statsLoading, setStatsLoading] = useState(true)
  const [checking, setChecking] = useState(false)
  const [result, setResult] = useState<ScanResult>(null)
  const [recentScans, setRecentScans] = useState<Array<{
    code: string
    result: ApiCheckInResult
    message: string
    checkedInAt?: string
  }>>([])

  // ΓöÇΓöÇ Load live stats ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const loadStats = useCallback(async () => {
    try {
      const s = await fetchCheckInStats(eventId)
      setStats(s)
    } catch {
      // Silently ignore poll errors ΓÇö don't disrupt scanning
    } finally {
      setStatsLoading(false)
    }
  }, [eventId])

  useEffect(() => {
    loadStats()
    const interval = setInterval(loadStats, POLL_INTERVAL_MS)
    return () => clearInterval(interval)
  }, [loadStats])

  // ΓöÇΓöÇ Handle scan ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const handleScan = async (raw: string) => {
    if (checkingRef.current) return
    checkingRef.current = true
    setChecking(true)

    try {
      const response = await checkInTicket({ ticketCode: raw.trim(), eventId })
      setResult(mapToScannerResult(response, raw))

      // Push to recent feed
      setRecentScans((prev) => [
        { code: raw.trim().toUpperCase(), ...response },
        ...prev.slice(0, 7),
      ])

      // Optimistically update counter on success
      if (response.result === "success") {
        setStats((prev) =>
          prev
            ? {
                ...prev,
                checkedIn: prev.checkedIn + 1,
                remaining: prev.remaining - 1,
                percent: prev.total > 0 ? Math.round(((prev.checkedIn + 1) / prev.total) * 100) : 0,
              }
            : prev
        )
      }
    } catch {
      setResult({ status: "invalid" })
    } finally {
      checkingRef.current = false
      setChecking(false)
    }
  }

  const pct = stats?.percent ?? 0

  return (
    <div className="space-y-6">
      {/* ΓöÇΓöÇ Hero header ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      <div className="relative overflow-hidden rounded-2xl border border-border bg-gradient-to-br from-primary/10 via-card to-card p-6 sm:p-8">
        <div className="flex flex-wrap items-center justify-between gap-6">
          <div className="min-w-0">
            <h1 className="text-2xl font-extrabold tracking-tight text-foreground sm:text-3xl">
              So├ít v├⌐ &amp; Check-in
            </h1>
            <p className="mt-1 text-sm text-muted-foreground">
              Sß╗▒ kiß╗çn ID: <span className="font-mono text-primary">{eventId}</span>
            </p>
          </div>

          {statsLoading ? (
            <Loader2 className="animate-spin text-primary" size={32} />
          ) : (
            <CheckInProgressRing value={pct} />
          )}
        </div>
      </div>

      {/* ΓöÇΓöÇ Live counters ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      <div className="grid grid-cols-3 gap-3 sm:gap-4">
        <StatCard icon={CheckCircle2} tone="emerald" value={stats?.checkedIn ?? 0} label="─É├ú check-in" />
        <StatCard icon={Clock} tone="amber" value={stats?.remaining ?? 0} label="Ch╞░a v├áo" />
        <StatCard icon={Ticket} tone="primary" value={stats?.total ?? 0} label="Tß╗òng v├⌐ ─æ├ú b├ín" />
      </div>

      {/* ΓöÇΓöÇ Scanner + recent feed ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      <div className="grid gap-6 lg:grid-cols-[1.4fr_1fr]">
        <CheckInScanner onScan={handleScan} result={result} disabled={checking} />

        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="text-base">Check-in gß║ºn ─æ├óy</CardTitle>
          </CardHeader>
          <CardContent>
            {recentScans.length === 0 ? (
              <p className="py-4 text-center text-sm text-muted-foreground">
                Ch╞░a c├│ l╞░ß╗út check-in n├áo.
              </p>
            ) : (
              <div>
                {recentScans.map((s, idx) => (
                  <div
                    key={`${s.code}-${idx}`}
                    className="flex items-center gap-3 border-t border-border py-2.5 first:border-t-0 first:pt-0"
                  >
                    <span
                      className={cn(
                        "grid h-9 w-9 shrink-0 place-items-center rounded-full text-sm font-bold",
                        s.result === "success"
                          ? "bg-emerald-500/15 text-emerald-600 dark:text-emerald-400"
                          : s.result === "duplicate"
                          ? "bg-amber-500/15 text-amber-600 dark:text-amber-400"
                          : "bg-destructive/15 text-destructive"
                      )}
                      aria-hidden="true"
                    >
                      {s.result === "success" ? "Γ£ô" : s.result === "duplicate" ? "ΓÜá" : "Γ£ù"}
                    </span>
                    <div className="min-w-0 flex-1">
                      <div className="truncate font-mono text-xs font-semibold text-foreground">
                        {s.code}
                      </div>
                      <div className="text-xs text-muted-foreground">{s.message}</div>
                    </div>
                    {s.checkedInAt && (
                      <span className="shrink-0 text-xs tabular-nums text-muted-foreground">
                        {new Date(s.checkedInAt).toLocaleTimeString("vi-VN", {
                          hour: "2-digit",
                          minute: "2-digit",
                        })}
                      </span>
                    )}
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    </div>
  )
}

