"use client"

import React, { createContext, useContext, useState, useEffect, ReactNode } from "react";
import { useRouter } from "next/navigation";
import { clientApi } from "@/lib/client-api";

export interface User {
  _id: string;
  fullName: string;
  email: string;
  phone?: string;
  role: "ADMIN" | "ORGANIZER" | "PARTICIPANT" | "STAFF";
  accountStatus: "ACTIVE" | "BANNED";
  avatar?: string;
  createdAt: string;
  updatedAt: string;
}

interface AuthContextType {
  user: User | null;
  loading: boolean;
  login: (email: string, passwordPlain: string) => Promise<void>;
  register: (data: any) => Promise<void>;
  loginWithGoogle: (credential: string) => Promise<void>;
  logout: () => Promise<void>;
  refreshUser: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const router = useRouter();

  const refreshUser = async () => {
    try {
      setLoading(true);
      const res = await clientApi.get<{ success: boolean; data: User }>("/users/me");
      if (res.success && res.data) {
        setUser(res.data);
      } else {
        setUser(null);
      }
    } catch (err) {
      // Ignore error when not authenticated on load
      setUser(null);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    refreshUser();
  }, []);

  const redirectBasedOnRole = (user: User) => {
    if (user.role === "ORGANIZER") {
      // Ban tß╗ò chß╗⌐c ΓåÆ khu vß╗▒c quß║ún l├╜ sß╗▒ kiß╗çn cß╗ºa hß╗ì
      router.push("/organizer");
    } else if (user.role === "STAFF") {
      // Nh├ón vi├¬n ΓåÆ trß║ím so├ít v├⌐ / check-in
      router.push("/staff");
    } else if (user.role === "ADMIN") {
      // Quß║ún trß╗ï ΓåÆ bß║úng ─æiß╗üu khiß╗ân hß╗ç thß╗æng
      router.push("/dashboard");
    } else {
      // PARTICIPANT ΓåÆ trang chß╗º
      router.push("/");
    }
  };

  const login = async (email: string, passwordPlain: string) => {
    const res = await clientApi.post<{ success: boolean; data: { user: User } }>("/users/login", {
      email,
      password: passwordPlain,
    });
    if (res.success && res.data.user) {
      setUser(res.data.user);
      redirectBasedOnRole(res.data.user);
    }
  };

  const register = async (data: any) => {
    const res = await clientApi.post<{ success: boolean; data: { user: User } }>("/users/register", data);
    if (res.success && res.data.user) {
      setUser(res.data.user);
      redirectBasedOnRole(res.data.user);
    }
  };

  const loginWithGoogle = async (credential: string) => {
    const res = await clientApi.post<{ success: boolean; data: { user: User } }>("/users/google", {
      credential,
    });
    if (res.success && res.data.user) {
      setUser(res.data.user);
      redirectBasedOnRole(res.data.user);
    }
  };

  const logout = async () => {
    try {
      await clientApi.post("/users/logout", {});
    } catch (err) {
      console.error("Logout request failed:", err);
    } finally {
      setUser(null);
      router.push("/login");
    }
  };

  return (
    <AuthContext.Provider
      value={{
        user,
        loading,
        login,
        register,
        loginWithGoogle,
        logout,
        refreshUser,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error("useAuth must be used within an AuthProvider");
  }
  return context;
}

/**
 * API Client for Client Components
 * Uses relative URLs that get proxied through Next.js rewrites
 */

const API_PREFIX = "/api";

interface ClientFetchOptions extends RequestInit {
  // Additional options for client-side fetching
}

class ClientApiClient {
  private prefix: string;

  constructor(prefix: string) {
    this.prefix = prefix;
  }

  private async request<T>(
    endpoint: string,
    options: ClientFetchOptions = {}
  ): Promise<T> {
    const url = `${this.prefix}${endpoint}`;

    const response = await fetch(url, {
      cache: "no-store",
      ...options,
      credentials: options.credentials || "include",
      headers: {
        "Content-Type": "application/json",
        ...options.headers,
      },
    });

    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      throw new Error(
        errorData.message || `API Error: ${response.status} ${response.statusText}`
      );
    }

    return response.json();
  }

  async get<T>(endpoint: string, options?: ClientFetchOptions): Promise<T> {
    return this.request<T>(endpoint, { ...options, method: "GET" });
  }

  async post<T>(
    endpoint: string,
    body: unknown,
    options?: ClientFetchOptions
  ): Promise<T> {
    return this.request<T>(endpoint, {
      ...options,
      method: "POST",
      body: JSON.stringify(body),
    });
  }

  async put<T>(
    endpoint: string,
    body: unknown,
    options?: ClientFetchOptions
  ): Promise<T> {
    return this.request<T>(endpoint, {
      ...options,
      method: "PUT",
      body: JSON.stringify(body),
    });
  }

  async patch<T>(
    endpoint: string,
    body: unknown,
    options?: ClientFetchOptions
  ): Promise<T> {
    return this.request<T>(endpoint, {
      ...options,
      method: "PATCH",
      body: JSON.stringify(body),
    });
  }

  async delete<T>(endpoint: string, options?: ClientFetchOptions): Promise<T> {
    return this.request<T>(endpoint, { ...options, method: "DELETE" });
  }
}

// Singleton instance for Client Components
export const clientApi = new ClientApiClient(API_PREFIX);

/**
 * Public event-discovery data layer ΓÇö homepage, /su-kien listing and detail.
 * Fetches the real backend public endpoints and maps the API shape onto the
 * presentational types the existing components already consume (EventItem,
 * ExploreEvent, FeaturedStar, banners, EventDetail), so wiring is a data-source
 * swap rather than a component rewrite.
 *
 * These run in Server Components, so an absolute backend URL is used (relative
 * "/api" only resolves in the browser via the Next.js rewrite).
 */
import type { EventItem } from "@/components/home/EventCard"
import type {
  ContentBlock,
  EventCity,
  ExploreEvent,
  FeaturedStar,
  ShowOption,
  TicketType,
} from "@/lib/mockData"

const API_BASE = process.env.NEXT_PUBLIC_API_URL || "http://localhost:5000"
const DEFAULT_EVENT_IMAGE = "/event-placeholder.svg"
const DEFAULT_AVATAR_IMAGE = "/avatar-placeholder.svg"

// ΓöÇΓöÇ Raw API shapes (subset we consume) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
interface ApiEvent {
  _id: string
  title: string
  date?: string
  time?: string
  startDate?: string
  location?: string
  imageUrl?: string
  banner?: string
  category?: string
  categorySlug?: string
  city?: EventCity
  priceFrom?: number
  isFree?: boolean
  isFeatured?: boolean
  isTrending?: boolean
  description?: string
  contentBlocks?: ContentBlock[]
  sessions?: { date?: string; time?: string; label?: string }[]
  shows?: { _id: string; title?: string; startTime: string; endTime: string }[]
  organizer?: string
  organizerLogoUrl?: string
  organizerDescription?: string
}

interface ApiTicket {
  _id: string
  ticketName: string
  price: number
  minPerOrder: number
  maxPerOrder: number
  showId?: string
}

interface ApiStar {
  _id: string
  name: string
  slug: string
  imageUrl?: string
  verified?: boolean
}

interface ApiBanner {
  _id: string
  title: string
  subtitle?: string
  imageUrl?: string
  ctaLabel?: string
  linkUrl?: string
}

/** GET /api/<path>; returns `data` (or the given fallback on any failure so a
 *  down backend degrades to an empty section instead of crashing the page). */
async function apiGet<T>(path: string, fallback: T): Promise<T> {
  try {
    const res = await fetch(`${API_BASE}/api${path}`, { cache: "no-store" })
    if (!res.ok) return fallback
    const json = await res.json()
    return (json.data ?? fallback) as T
  } catch {
    return fallback
  }
}

// ΓöÇΓöÇ Formatting helpers (match the existing mock display strings) ΓöÇΓöÇΓöÇΓöÇΓöÇ
function formatDate(iso?: string): string {
  if (!iso) return "Ch╞░a ─æß║╖t lß╗ïch"
  const d = new Date(iso)
  if (Number.isNaN(d.getTime())) return "Ch╞░a ─æß║╖t lß╗ïch"
  const pad = (n: number) => String(n).padStart(2, "0")
  return `${pad(d.getDate())}/${pad(d.getMonth() + 1)}/${d.getFullYear()}`
}

function formatPrice(priceFrom?: number, isFree?: boolean): string {
  if (isFree || !priceFrom) return "Miß╗àn ph├¡"
  return `Tß╗½ ${priceFrom.toLocaleString("vi-VN")}─æ`
}

const eventImage = (e: ApiEvent) => e.imageUrl || e.banner || DEFAULT_EVENT_IMAGE

/** Event.shows[] ΓåÆ presentational options, oldest first, auto-labelled when the
 *  organizer didn't name the showing ("Suß║Ñt chiß╗üu" etc). */
function toShowOptions(shows: ApiEvent["shows"]): ShowOption[] {
  return [...(shows ?? [])]
    .sort((a, b) => new Date(a.startTime).getTime() - new Date(b.startTime).getTime())
    .map((s, i) => ({
      id: s._id,
      label: s.title?.trim() || `Suß║Ñt ${i + 1}`,
      startTime: s.startTime,
      endTime: s.endTime,
    }))
}

// ΓöÇΓöÇ Mappers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
function toEventItem(e: ApiEvent): EventItem {
  return {
    id: e._id,
    title: e.title,
    date: formatDate(e.date ?? e.startDate),
    time: e.time || "",
    location: e.location || "─Éang cß║¡p nhß║¡t",
    price: formatPrice(e.priceFrom, e.isFree),
    image: eventImage(e),
    category: e.category || "Sß╗▒ kiß╗çn",
  }
}

function toExploreEvent(e: ApiEvent): ExploreEvent {
  const collections = [
    ...(e.isFeatured ? ["featured"] : []),
    ...(e.isTrending ? ["trending"] : []),
    "upcoming",
  ]
  return {
    ...toEventItem(e),
    isFeatured: e.isFeatured,
    city: e.city ?? "other",
    categorySlug: e.categorySlug || "khac",
    isFree: e.isFree ?? false,
    collections,
  }
}

// ΓöÇΓöÇ Public fetchers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
export interface HomeData {
  banners: { id: string; title: string; subtitle: string; image: string; cta: string; link: string }[]
